DRAWING_NUMBER_NOT_FOUND = "NO DRAWING NUMBER EXTRACTED"
DRAWING_TITLE_NOT_FOUND = "DRAWING TITLE NOT FOUND"

CAD_EXTENSIONS = {
    ".dwg", ".dxf", ".dgn", ".rvt", ".rfa", ".ifc",
    ".nwc", ".nwd", ".step", ".stp",
}

DRAWING_CODE_RE = re.compile(r"\b[A-Za-z0-9]+(?:-[A-Za-z0-9]+){4,}\b")


def normalize_spaces(value: str) -> str:
    return re.sub(r"\s+", " ", (value or "").strip())


def normalize_vector(vector):
    x, y = float(vector[0]), float(vector[1])
    length = math.hypot(x, y)
    if length < 1e-9:
        return (1.0, 0.0)
    return (x / length, y / length)


def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]


def center_of_bbox(bbox):
    x0, y0, x1, y1 = bbox
    return ((x0 + x1) / 2.0, (y0 + y1) / 2.0)


def filename_stem_without_suffixes(path: Path) -> str:
    stem = re.sub(
        r"(?:[_\-\s]+)(PDF|DWG|DXF)$", "", path.stem, flags=re.I
    ).strip()
    # Windows may create duplicate-download suffixes such as "(1)".
    # These are never part of an engineering drawing number.
    stem = re.sub(r"\s*\(\d+\)\s*$", "", stem).strip()
    return stem


def normalize_filename_drawing_candidate(value: str) -> str:
    """Normalize a filename-derived candidate for secondary file matching only.

    Contractor PDF/CAD filenames occasionally append the revision after the
    real drawing number, for example ``...-0102572-01``.  The authoritative
    PDF metadata extractor must *not* use this helper; it remains title-block
    only.  This helper merely makes CAD/file matching tolerant of a trailing
    two-digit revision and Windows duplicate suffixes such as ``(1)``.
    """
    value = normalize_spaces(value).upper()
    value = re.sub(r"\s*\(\d+\)\s*$", "", value).strip()
    # Strip only an appended two-digit revision token.  Normal drawing-number
    # endings such as ``...-0130000`` are therefore preserved unchanged.
    value = re.sub(r"[-_](?:REV[-_ ]*)?\d{2}$", "", value, flags=re.I).strip("-_ ")
    return value


def infer_drawing_number_from_filename(path: Path) -> str:
    """CAD/file matching only. Never used to derive PDF metadata."""
    stem = filename_stem_without_suffixes(path)
    matches = DRAWING_CODE_RE.findall(stem)
    if matches:
        candidate = max(matches, key=len).upper()
        return normalize_filename_drawing_candidate(candidate)
    return normalize_filename_drawing_candidate(stem)


def get_pdf_lines(page):
    """Extract PDF text lines including writing direction."""
    results = []
    try:
        data = page.get_text("dict", sort=False)
    except Exception:
        return results

    for block in data.get("blocks", []):
        if block.get("type", 0) != 0:
            continue
        for line in block.get("lines", []):
            pieces = []
            for span in line.get("spans", []):
                text = normalize_spaces(span.get("text", ""))
                if text:
                    pieces.append(text)
            text = normalize_spaces(" ".join(pieces))
            bbox = line.get("bbox")
            if not text or not bbox:
                continue
            bbox = tuple(float(v) for v in bbox)
            direction = normalize_vector(line.get("dir", (1.0, 0.0)))
            results.append({
                "text": text,
                "upper": text.upper(),
                "bbox": bbox,
                "center": center_of_bbox(bbox),
                "dir": direction,
            })
    return results


def find_exact_label(lines, label: str):
    wanted = normalize_spaces(label).upper()
    matches = [line for line in lines if line["upper"] == wanted]
    if not matches:
        return None
    # Works for normal bottom/right title blocks and the rotated right-edge block.
    return max(matches, key=lambda line: line["center"][0] + line["center"][1])


def same_orientation(a, b, threshold=0.80):
    return dot(a, b) >= threshold


def orthogonal_field_direction(text_dir, raw_vector=None):
    """Return a unit vector perpendicular to text_dir, oriented by raw_vector if supplied."""
    u = normalize_vector(text_dir)
    if raw_vector is not None:
        raw = (float(raw_vector[0]), float(raw_vector[1]))
        projection = dot(raw, u)
        perpendicular = (raw[0] - projection * u[0], raw[1] - projection * u[1])
        if math.hypot(*perpendicular) > 1e-6:
            return normalize_vector(perpendicular)
    return normalize_vector((-u[1], u[0]))


def local_position(origin, point, text_dir, field_dir):
    delta = (point[0] - origin[0], point[1] - origin[1])
    return dot(delta, text_dir), dot(delta, field_dir)


def get_title_block_basis(lines):
    """
    Build a rotation-aware local coordinate system.

    u = direction in which title-block text is written.
    v = direction from DRAWING TITLE toward PURPOSE OF ISSUE.

    On the user's failed page 51, u=(0,-1) and v=(1,0), so values that are
    visually 'below' the label are actually to the right in PDF coordinates.
    """
    title_label = find_exact_label(lines, "DRAWING TITLE")
    if not title_label:
        return None

    u = normalize_vector(title_label["dir"])
    purpose = find_exact_label(lines, "PURPOSE OF ISSUE")

    if purpose and same_orientation(purpose["dir"], u):
        raw = (
            purpose["center"][0] - title_label["center"][0],
            purpose["center"][1] - title_label["center"][1],
        )
        v = orthogonal_field_direction(u, raw)
        purpose_distance = dot(raw, v)
        if purpose_distance < 0:
            v = (-v[0], -v[1])
            purpose_distance = -purpose_distance
        if purpose_distance > 1:
            return title_label, purpose, u, v, purpose_distance

    # Fallback: use DRAWING NUMBER to determine which perpendicular side is
    # deeper into the title block. This still does not use the number VALUE.
    number_label = find_exact_label(lines, "DRAWING NUMBER")
    if number_label and same_orientation(number_label["dir"], u):
        raw = (
            number_label["center"][0] - title_label["center"][0],
            number_label["center"][1] - title_label["center"][1],
        )
        v = orthogonal_field_direction(u, raw)
        if dot(raw, v) < 0:
            v = (-v[0], -v[1])
        return title_label, None, u, v, None

    return title_label, None, u, orthogonal_field_direction(u), None


def valid_title_line(text: str) -> bool:
    value = normalize_spaces(text)
    if not value:
        return False
    upper = value.upper()

    reject_exact = {
        "DRAWING TITLE", "PURPOSE OF ISSUE", "PROJECT TITLE",
        "DRAWING NUMBER", "REVISION NO", "MODEL FILE REF", "SCALE",
        "DRAWN", "CHECKED", "DESIGNED", "APPROVED", "SEAL DATE",
        "SEAL DATE:", "CLIENT", "DRAWN CHECKED", "DESIGNED APPROVED",
    }
    if upper in reject_exact:
        return False

    reject_contains = (
        "ISSUED FOR", "NOT EXTRACTED FROM MODEL", "FIRST ISSUE",
        "DRAWING REVISIONS", "COPYRIGHT", "PLEASE REFER", "WWW.",
        "DO NOT SCALE",
    )
    if any(term in upper for term in reject_contains):
        return False
    if DRAWING_CODE_RE.search(value):
        return False
    if re.fullmatch(r"\d{1,2}/\d{1,2}/\d{2,4}", value):
        return False
    if re.fullmatch(r"\d+\s*:\s*\d+", value):
        return False
    if re.fullmatch(r"\d{1,2}", value):
        return False
    return sum(ch.isalpha() for ch in value) >= 3


def extract_drawing_title(page, lines=None) -> str:
    """
    Extract ONLY the value in the fixed DRAWING TITLE cell.
    Rotation-aware: does not assume that visually 'below' means +Y.
    CAD is never consulted.
    """
    lines = get_pdf_lines(page) if lines is None else lines
    basis = get_title_block_basis(lines)
    if not basis:
        return DRAWING_TITLE_NOT_FOUND

    title_label, purpose_label, u, v, purpose_distance = basis
    origin = title_label["center"]
    page_size = max(float(page.rect.width), float(page.rect.height))

    # Field depth is bounded by PURPOSE OF ISSUE when available.
    if purpose_distance is not None:
        max_field = max(8.0, purpose_distance - 2.0)
    else:
        max_field = page_size * 0.035

    # The value can be long in the text-writing direction, especially on
    # rotated A0 pages, so allow enough room while staying local to the cell.
    min_along = -page_size * 0.02
    max_along = page_size * 0.22

    candidates = []
    for line in lines:
        if line is title_label or line is purpose_label:
            continue
        if not same_orientation(line["dir"], u):
            continue
        along, field = local_position(origin, line["center"], u, v)
        if field <= 1.0 or field >= max_field:
            continue
        if along < min_along or along > max_along:
            continue
        text = normalize_spaces(line["text"])
        if not valid_title_line(text):
            continue
        candidates.append((field, along, line))

    if not candidates:
        return DRAWING_TITLE_NOT_FOUND

    # Order by movement across the title cell. This correctly gives
    # "LOADPLANS... LEVEL" then "ROOF" on the rotated failed page.
    candidates.sort(key=lambda item: (item[0], item[1]))

    parts = []
    for _, _, line in candidates:
        text = normalize_spaces(line["text"])
        if text and text not in parts:
            parts.append(text)

    title = normalize_spaces(" ".join(parts)).upper()
    return title if title else DRAWING_TITLE_NOT_FOUND


def extract_drawing_number(page, lines=None) -> str:
    """
    Extract ONLY the value in the fixed DRAWING NUMBER cell.
    Uses the same rotation-aware title-block basis as the title extractor.
    No PDF filename, CAD filename, references, or callouts are used.
    """
    lines = get_pdf_lines(page) if lines is None else lines
    number_label = find_exact_label(lines, "DRAWING NUMBER")
    if not number_label:
        return DRAWING_NUMBER_NOT_FOUND

    basis = get_title_block_basis(lines)
    if basis:
        _, _, u, v, _ = basis
        if not same_orientation(number_label["dir"], u):
            u = normalize_vector(number_label["dir"])
            v = orthogonal_field_direction(u)
    else:
        u = normalize_vector(number_label["dir"])
        v = orthogonal_field_direction(u)

    # Make sure v points from the label toward the actual lower/deeper title
    # block side. When DRAWING TITLE/PURPOSE exists, get_title_block_basis
    # already establishes this. Otherwise infer sign from nearby labels.
    if not basis:
        for label_name in ("PURPOSE OF ISSUE", "PROJECT TITLE", "SCALE"):
            neighbor = find_exact_label(lines, label_name)
            if neighbor and same_orientation(neighbor["dir"], u):
                raw = (
                    number_label["center"][0] - neighbor["center"][0],
                    number_label["center"][1] - neighbor["center"][1],
                )
                candidate_v = orthogonal_field_direction(u, raw)
                if dot(raw, candidate_v) < 0:
                    candidate_v = (-candidate_v[0], -candidate_v[1])
                v = candidate_v
                break

    origin = number_label["center"]
    page_size = max(float(page.rect.width), float(page.rect.height))
    max_field = page_size * 0.045
    min_along = -page_size * 0.025
    max_along = page_size * 0.22

    candidates = []
    for line in lines:
        if line is number_label:
            continue
        if not same_orientation(line["dir"], u):
            continue
        along, field = local_position(origin, line["center"], u, v)
        if field <= 1.0 or field > max_field:
            continue
        if along < min_along or along > max_along:
            continue

        text = normalize_spaces(line["text"])
        variants = [text, re.sub(r"\s+", "", text)]
        for variant in variants:
            for match in DRAWING_CODE_RE.findall(variant):
                code = match.upper()
                if DRAWING_CODE_RE.fullmatch(code):
                    candidates.append((field, abs(along), code))

    if not candidates:
        return DRAWING_NUMBER_NOT_FOUND

    candidates.sort(key=lambda item: (item[0], item[1]))
    return candidates[0][2]


def extract_revision_no(page, lines=None) -> str:
    """Extract ONLY the value in the title-block REVISION NO cell.

    The PDF title block remains authoritative. Filename revision suffixes are
    deliberately ignored here and are used only by secondary filename matching.
    """
    lines = get_pdf_lines(page) if lines is None else lines
    revision_label = find_exact_label(lines, "REVISION NO")
    if not revision_label:
        # Some PDF producers merge adjacent title-block labels into one text
        # line (for example: "SCALE A0 (841x1189) REVISION NO").  Accept that
        # only as a label locator; the revision value itself is still extracted
        # geometrically from the REVISION NO title-block cell.
        merged_labels = [line for line in lines if "REVISION NO" in line.get("upper", "")]
        if merged_labels:
            revision_label = min(merged_labels, key=lambda line: len(line.get("upper", "")))
    if not revision_label:
        return ""

    basis = get_title_block_basis(lines)
    if basis:
        _, _, u, v, _ = basis
        if not same_orientation(revision_label["dir"], u):
            u = normalize_vector(revision_label["dir"])
            v = orthogonal_field_direction(u)
    else:
        u = normalize_vector(revision_label["dir"])
        v = orthogonal_field_direction(u)

    origin = revision_label["center"]
    # Use the page dimensions without assuming a specific PDF engine object.
    try:
        page_size = max(float(page.rect.width), float(page.rect.height))
    except Exception:
        page_size = max(float(getattr(page, "width", 0.0)), float(getattr(page, "height", 0.0)), 1000.0)

    # Revision values are very close to the exact REVISION NO label.  Keep the
    # search local so revision-history tables elsewhere on the sheet cannot win.
    max_along = page_size * 0.035
    max_field = page_size * 0.035
    candidates = []
    for line in lines:
        if line is revision_label:
            continue
        if not same_orientation(line["dir"], u):
            continue
        along, field = local_position(origin, line["center"], u, v)
        if abs(along) > max_along or field <= 1.0 or field > max_field:
            continue
        text = normalize_spaces(line["text"]).upper()
        # Supports common numeric and short alphanumeric revisions: 00, 01,
        # A, B, P01, C02, etc., while remaining strict to the title-block cell.
        if not re.fullmatch(r"[A-Z0-9]{1,3}", text):
            continue
        candidates.append((field, abs(along), text))

    if not candidates:
        return ""
    candidates.sort(key=lambda item: (item[0], item[1]))
    return candidates[0][2]


def infer_category(title: str) -> str:
    upper = normalize_spaces(title).upper()
    if not upper or upper == DRAWING_TITLE_NOT_FOUND:
        return "UNRESOLVED"
    if "ROOF" in upper or "ENVELOPE" in upper:
        return "ROOF / ENVELOPE"
    if "CURVED WALL" in upper or "BALCONY" in upper or "BALCONIES" in upper:
        return "WALLS / BALCONIES"
    if "CANOPY" in upper or "CANOPIES" in upper:
        return "CANOPIES"
    if "BLEACHER" in upper or "BLEACHERS" in upper or "SEATING" in upper:
        return "BLEACHERS"
    if "STAIR" in upper or "STAIRS" in upper or "STAIRCASE" in upper:
        return "STAIRS"
    if "TRUSS" in upper or "TRUSSES" in upper:
        return "TRUSSES"
    if any(x in upper for x in ("FOUNDATION", "FOOTING", "PILE CAP")):
        return "FOUNDATIONS"
    if "COLUMN" in upper:
        return "COLUMNS"
    if "BEAM" in upper or "GIRDER" in upper:
        return "BEAMS"
    if "SLAB" in upper:
        return "SLABS"
    if "WALL" in upper:
        return "WALLS"
    if any(x in upper for x in ("GENERAL ARRANGEMENT", "FLOOR PLAN", "ROOF PLAN", "LAYOUT", " PLAN")):
        return "PLANS"
    if "SECTION" in upper:
        return "SECTIONS"
    if "ELEVATION" in upper:
        return "ELEVATIONS"
    if "CONNECTION" in upper or "JOINT" in upper:
        return "CONNECTIONS"
    if "SCHEDULE" in upper:
        return "SCHEDULES"
    if "GENERAL NOTES" in upper or "LEGEND" in upper:
        return "GENERAL / NOTES"
    if "DETAIL" in upper:
        return "DETAILS"
    if "STEEL" in upper:
        return "STEEL"
    if "CONCRETE" in upper or "REINFORCEMENT" in upper or "REBAR" in upper:
        return "CONCRETE"
    return "OTHER"


def open_path(path: str):
    if not path:
        raise FileNotFoundError("No file is linked.")
    p = Path(path)
    if not p.exists():
        raise FileNotFoundError(str(p))
    system = platform.system()
    if system == "Windows":
        os.startfile(str(p))
    elif system == "Darwin":
        subprocess.Popen(["open", str(p)])
    else:
        subprocess.Popen(["xdg-open", str(p)])


def open_pdf_at_page(pdf_path: str, page_number: int):
    path = Path(pdf_path)
    if not path.exists():
        raise FileNotFoundError(str(path))
    page_number = max(1, int(page_number or 1))
    try:
        uri = f"{path.resolve().as_uri()}#page={page_number}"
        if not webbrowser.open(uri, new=2):
            open_path(str(path))
    except Exception:
        open_path(str(path))


def reveal_path(path: str):
    if not path:
        return
    p = Path(path)
    if not p.exists():
        return
    system = platform.system()
    if system == "Windows":
        subprocess.Popen(["explorer", "/select,", str(p)])
    elif system == "Darwin":
        subprocess.Popen(["open", "-R", str(p)])
    else:
        subprocess.Popen(["xdg-open", str(p.parent)])


class DrawingDB:
    """Thread-safe SQLite index tuned for a large drawing register."""

    def __init__(self, db_path: Path):
        self.conn = sqlite3.connect(
            str(db_path),
            check_same_thread=False,
            timeout=30.0,
        )
        self.conn.row_factory = sqlite3.Row
        self.lock = threading.RLock()
        self._configure_connection()
        self.setup()

    def _configure_connection(self):
        # These settings materially reduce UI stalls while the background indexer
        # is writing thousands of pages.
        pragmas = (
            "PRAGMA journal_mode=WAL",
            "PRAGMA synchronous=NORMAL",
            "PRAGMA temp_store=MEMORY",
            "PRAGMA cache_size=-32768",
            "PRAGMA mmap_size=268435456",
            "PRAGMA busy_timeout=30000",
        )
        with self.lock:
            for statement in pragmas:
                try:
                    self.conn.execute(statement)
                except sqlite3.Error:
                    pass

    def setup(self):
        with self.lock, self.conn:
            self.conn.execute("""
                CREATE TABLE IF NOT EXISTS master_pages (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    pdf_path TEXT NOT NULL,
                    pdf_page INTEGER NOT NULL,
                    pdf_pages INTEGER NOT NULL DEFAULT 1,
                    drawing_number TEXT NOT NULL DEFAULT 'NO DRAWING NUMBER EXTRACTED',
                    title TEXT NOT NULL DEFAULT 'DRAWING TITLE NOT FOUND',
                    revision TEXT NOT NULL DEFAULT '',
                    category TEXT NOT NULL DEFAULT 'UNRESOLVED',
                    source_type TEXT NOT NULL DEFAULT 'BOUND',
                    source_priority INTEGER NOT NULL DEFAULT 0,
                    preferred INTEGER NOT NULL DEFAULT 1,
                    cad_path TEXT NOT NULL DEFAULT '',
                    UNIQUE(pdf_path, pdf_page)
                )
            """)
            # Backward-compatible migration: existing v15 databases gain the
            # revision column without changing the DB/config lineage.
            columns = {row[1] for row in self.conn.execute("PRAGMA table_info(master_pages)").fetchall()}
            if "revision" not in columns:
                self.conn.execute("ALTER TABLE master_pages ADD COLUMN revision TEXT NOT NULL DEFAULT ''")
            self.conn.execute("CREATE INDEX IF NOT EXISTS idx_master_revision_nocase_fast ON master_pages(revision COLLATE NOCASE)")
            self.conn.execute("CREATE INDEX IF NOT EXISTS idx_master_number_nocase_fast ON master_pages(drawing_number COLLATE NOCASE)")
            self.conn.execute("CREATE INDEX IF NOT EXISTS idx_master_title_nocase_fast ON master_pages(title COLLATE NOCASE)")
            self.conn.execute("CREATE INDEX IF NOT EXISTS idx_master_category_nocase_fast ON master_pages(category COLLATE NOCASE)")
            self.conn.execute("CREATE INDEX IF NOT EXISTS idx_master_preferred ON master_pages(preferred)")
            self.conn.execute("CREATE INDEX IF NOT EXISTS idx_master_page_order ON master_pages(preferred, source_priority, pdf_path, pdf_page)")
            self.conn.execute("CREATE INDEX IF NOT EXISTS idx_master_preferred_page ON master_pages(preferred, pdf_page)")
            self.conn.execute("""
                CREATE TABLE IF NOT EXISTS unmatched_cad (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    cad_path TEXT UNIQUE NOT NULL,
                    guessed_drawing_number TEXT NOT NULL DEFAULT ''
                )
            """)
            self.conn.execute("""
                CREATE TABLE IF NOT EXISTS pdf_file_cache (
                    pdf_path TEXT PRIMARY KEY,
                    size_bytes INTEGER NOT NULL DEFAULT 0,
                    mtime_ns INTEGER NOT NULL DEFAULT 0,
                    page_count INTEGER NOT NULL DEFAULT 0,
                    source_type TEXT NOT NULL DEFAULT 'BOUND',
                    source_priority INTEGER NOT NULL DEFAULT 0,
                    engine_tag TEXT NOT NULL DEFAULT ''
                )
            """)
        try:
            with self.lock:
                self.conn.execute("PRAGMA optimize")
        except sqlite3.Error:
            pass

    def close(self):
        with self.lock:
            try:
                self.conn.close()
            except Exception:
                pass

    def clear_all(self):
        with self.lock, self.conn:
            self.conn.execute("DELETE FROM master_pages")
            self.conn.execute("DELETE FROM unmatched_cad")
            self.conn.execute("DELETE FROM pdf_file_cache")

    @staticmethod
    def _normalise_record(record):
        (pdf_path, pdf_page, pdf_pages, drawing_number, title, revision, category,
         source_type, source_priority) = record
        return (
            str(pdf_path),
            int(pdf_page),
            int(pdf_pages),
            normalize_spaces(drawing_number).upper() or DRAWING_NUMBER_NOT_FOUND,
            normalize_spaces(title).upper() or DRAWING_TITLE_NOT_FOUND,
            normalize_spaces(revision).upper(),
            normalize_spaces(category).upper() or "UNRESOLVED",
            normalize_spaces(source_type).upper() or "BOUND",
            int(source_priority),
        )

    def bulk_insert_master_pages(self, records):
        records = [self._normalise_record(record) for record in records]
        if not records:
            return
        sql = """
            INSERT INTO master_pages
                (pdf_path, pdf_page, pdf_pages, drawing_number, title, revision, category,
                 source_type, source_priority, preferred, cad_path)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 1, '')
            ON CONFLICT(pdf_path, pdf_page) DO UPDATE SET
                pdf_pages = excluded.pdf_pages,
                drawing_number = excluded.drawing_number,
                title = excluded.title,
                revision = excluded.revision,
                category = excluded.category,
                source_type = excluded.source_type,
                source_priority = excluded.source_priority
        """
        with self.lock, self.conn:
            self.conn.executemany(sql, records)

    def insert_master_page(self, pdf_path, pdf_page, pdf_pages, drawing_number, title, revision, category,
                           source_type="BOUND", source_priority=0):
        self.bulk_insert_master_pages([(
            pdf_path, pdf_page, pdf_pages, drawing_number, title, revision, category,
            source_type, source_priority,
        )])

    def pdf_cache_map(self):
        with self.lock:
            rows = self.conn.execute("""
                SELECT pdf_path, size_bytes, mtime_ns, page_count,
                       source_type, source_priority, engine_tag
                FROM pdf_file_cache
            """).fetchall()
        return {str(row[0]): row for row in rows}

    def replace_pdf_records(self, pdf_path, records, cache_record):
        """Atomically replace one PDF only after its complete scan succeeds."""
        normalized = [self._normalise_record(record) for record in records]
        sql = """
            INSERT INTO master_pages
                (pdf_path, pdf_page, pdf_pages, drawing_number, title, revision, category,
                 source_type, source_priority, preferred, cad_path)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 1, '')
        """
        path_text = str(pdf_path)
        size_bytes, mtime_ns, page_count, source_type, source_priority, engine_tag = cache_record
        with self.lock, self.conn:
            self.conn.execute("DELETE FROM master_pages WHERE pdf_path = ?", (path_text,))
            if normalized:
                self.conn.executemany(sql, normalized)
            self.conn.execute("""
                INSERT INTO pdf_file_cache
                    (pdf_path, size_bytes, mtime_ns, page_count,
                     source_type, source_priority, engine_tag)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(pdf_path) DO UPDATE SET
                    size_bytes = excluded.size_bytes,
                    mtime_ns = excluded.mtime_ns,
                    page_count = excluded.page_count,
                    source_type = excluded.source_type,
                    source_priority = excluded.source_priority,
                    engine_tag = excluded.engine_tag
            """, (
                path_text, int(size_bytes), int(mtime_ns), int(page_count),
                str(source_type), int(source_priority), str(engine_tag),
            ))

    def prune_pdf_paths(self, valid_paths):
        """Remove records for PDFs no longer present in the configured work list."""
        valid = {str(value) for value in valid_paths}
        with self.lock, self.conn:
            existing = [str(row[0]) for row in self.conn.execute(
                "SELECT DISTINCT pdf_path FROM master_pages"
            ).fetchall()]
            stale = [path for path in existing if path not in valid]
            if stale:
                self.conn.executemany("DELETE FROM master_pages WHERE pdf_path = ?", [(p,) for p in stale])
            cache_paths = [str(row[0]) for row in self.conn.execute(
                "SELECT pdf_path FROM pdf_file_cache"
            ).fetchall()]
            stale_cache = [path for path in cache_paths if path not in valid]
            if stale_cache:
                self.conn.executemany("DELETE FROM pdf_file_cache WHERE pdf_path = ?", [(p,) for p in stale_cache])

    def recalculate_preferred(self):
        """Resolve duplicates in one SQL operation instead of one transaction per drawing."""
        with self.lock, self.conn:
            self.conn.execute("UPDATE master_pages SET preferred = 1")
            try:
                self.conn.execute("""
                    WITH ranked AS (
                        SELECT
                            id,
                            ROW_NUMBER() OVER (
                                PARTITION BY drawing_number COLLATE NOCASE
                                ORDER BY source_priority ASC,
                                         pdf_pages DESC,
                                         pdf_path COLLATE NOCASE ASC,
                                         pdf_page ASC
                            ) AS rn
                        FROM master_pages
                        WHERE drawing_number <> ?
                    )
                    UPDATE master_pages
                    SET preferred = CASE
                        WHEN id IN (SELECT id FROM ranked WHERE rn = 1) THEN 1
                        ELSE 0
                    END
                    WHERE drawing_number <> ?
                """, (DRAWING_NUMBER_NOT_FOUND, DRAWING_NUMBER_NOT_FOUND))
            except sqlite3.OperationalError:
                # Compatibility fallback for unusually old SQLite builds.
                duplicate_numbers = self.conn.execute("""
                    SELECT drawing_number FROM master_pages
                    WHERE drawing_number <> ?
                    GROUP BY drawing_number COLLATE NOCASE
                    HAVING COUNT(*) > 1
                """, (DRAWING_NUMBER_NOT_FOUND,)).fetchall()
                for row in duplicate_numbers:
                    number = row[0]
                    records = self.conn.execute("""
                        SELECT id FROM master_pages
                        WHERE drawing_number = ? COLLATE NOCASE
                        ORDER BY source_priority ASC, pdf_pages DESC,
                                 pdf_path COLLATE NOCASE, pdf_page ASC
                    """, (number,)).fetchall()
                    if records:
                        keep_id = records[0][0]
                        self.conn.execute(
                            "UPDATE master_pages SET preferred = CASE WHEN id = ? THEN 1 ELSE 0 END "
                            "WHERE drawing_number = ? COLLATE NOCASE",
                            (keep_id, number),
                        )

    def drawing_exists(self, drawing_number):
        if not drawing_number or drawing_number == DRAWING_NUMBER_NOT_FOUND:
            return None
        with self.lock:
            return self.conn.execute("""
                SELECT * FROM master_pages
                WHERE drawing_number = ? COLLATE NOCASE
                ORDER BY preferred DESC, source_priority ASC
                LIMIT 1
            """, (drawing_number,)).fetchone()

    def drawing_number_set(self):
        with self.lock:
            rows = self.conn.execute("""
                SELECT DISTINCT drawing_number FROM master_pages
                WHERE drawing_number <> ?
            """, (DRAWING_NUMBER_NOT_FOUND,)).fetchall()
        return {normalize_spaces(row[0]).upper() for row in rows if row[0]}

    def attach_cad(self, drawing_number, cad_path):
        self.bulk_attach_cad([(drawing_number, cad_path)])

    def bulk_attach_cad(self, matches):
        values = [
            (str(cad_path), normalize_spaces(number).upper())
            for number, cad_path in matches
            if number and number != DRAWING_NUMBER_NOT_FOUND
        ]
        if not values:
            return
        with self.lock, self.conn:
            self.conn.executemany("""
                UPDATE master_pages SET cad_path = ?
                WHERE drawing_number = ? COLLATE NOCASE
            """, values)

    def clear_cad_links(self):
        with self.lock, self.conn:
            self.conn.execute("UPDATE master_pages SET cad_path = ''")
            self.conn.execute("DELETE FROM unmatched_cad")

    def add_unmatched_cad(self, cad_path, guessed_number):
        self.bulk_add_unmatched_cad([(cad_path, guessed_number)])

    def bulk_add_unmatched_cad(self, records):
        values = [(str(path), guessed or "") for path, guessed in records]
        if not values:
            return
        with self.lock, self.conn:
            self.conn.executemany("""
                INSERT OR REPLACE INTO unmatched_cad(cad_path, guessed_drawing_number)
                VALUES (?, ?)
            """, values)

    def get_by_id(self, row_id):
        with self.lock:
            return self.conn.execute(
                "SELECT * FROM master_pages WHERE id = ?", (int(row_id),)
            ).fetchone()

    def categories(self):
        with self.lock:
            rows = self.conn.execute("""
                SELECT DISTINCT category FROM master_pages
                WHERE category <> ''
                ORDER BY category COLLATE NOCASE
            """).fetchall()
        return [row[0] for row in rows]

    @staticmethod
    def _filter_sql(text="", category="ALL", unresolved_only=False, show_duplicates=False):
        clauses, params = [], []
        if not show_duplicates:
            clauses.append("preferred = 1")
        for term in [x for x in re.split(r"\s+", (text or "").strip()) if x]:
            like = f"%{term}%"
            clauses.append("""
                (drawing_number LIKE ? OR title LIKE ? OR revision LIKE ? OR category LIKE ? OR source_type LIKE ?
                 OR pdf_path LIKE ? OR CAST(pdf_page AS TEXT) LIKE ?)
            """)
            params.extend([like, like, like, like, like, like, like])
        if category and category != "ALL":
            clauses.append("category = ?")
            params.append(category)
        if unresolved_only:
            clauses.append("""
                (drawing_number = 'NO DRAWING NUMBER EXTRACTED'
                 OR title = 'DRAWING TITLE NOT FOUND'
                 OR category = 'UNRESOLVED')
            """)
        where = "WHERE " + " AND ".join(clauses) if clauses else ""
        return where, params

    @staticmethod
    def _order_sql(sort_column="page", reverse=False):
        expressions = {
            "idx": "id",
            "drawing_number": "drawing_number COLLATE NOCASE",
            "title": "title COLLATE NOCASE",
            "category": "category COLLATE NOCASE",
            "revision": "revision COLLATE NOCASE",
            "source": "pdf_path COLLATE NOCASE",
            "page": "pdf_page",
            "status": "CASE WHEN cad_path <> '' THEN 1 ELSE 0 END",
        }
        expression = expressions.get(sort_column, "pdf_page")
        direction = "DESC" if reverse else "ASC"
        return (
            f"{expression} {direction}, source_priority ASC, "
            "pdf_path COLLATE NOCASE ASC, pdf_page ASC, id ASC"
        )

    def search_count(self, text="", category="ALL", unresolved_only=False, show_duplicates=False):
        where, params = self._filter_sql(text, category, unresolved_only, show_duplicates)
        with self.lock:
            row = self.conn.execute(
                f"SELECT COUNT(*) AS total FROM master_pages {where}", params
            ).fetchone()
        return int(row["total"] or 0)

    def search_page(self, text="", category="ALL", unresolved_only=False,
                    show_duplicates=False, limit=15, offset=0,
                    sort_column="page", sort_reverse=False):
        where, params = self._filter_sql(text, category, unresolved_only, show_duplicates)
        order = self._order_sql(sort_column, sort_reverse)
        params.extend([max(1, int(limit)), max(0, int(offset))])
        with self.lock:
            return self.conn.execute(f"""
                SELECT mp.*,
                       CASE
                           WHEN mp.drawing_number = 'NO DRAWING NUMBER EXTRACTED' THEN 1
                           ELSE (
                               SELECT COUNT(*)
                               FROM master_pages AS dup
                               WHERE dup.drawing_number = mp.drawing_number
                           )
                       END AS duplicate_count
                FROM master_pages AS mp
                {where}
                ORDER BY {order}
                LIMIT ? OFFSET ?
            """, params).fetchall()

    def search(self, text="", category="ALL", unresolved_only=False,
               show_duplicates=False, limit=50000):
        return self.search_page(
            text=text,
            category=category,
            unresolved_only=unresolved_only,
            show_duplicates=show_duplicates,
            limit=limit,
            offset=0,
            sort_column="page",
            sort_reverse=False,
        )

    def stats(self):
        with self.lock:
            row = self.conn.execute("""
                SELECT
                    COUNT(*) AS pages,
                    SUM(CASE WHEN preferred = 1 THEN 1 ELSE 0 END) AS preferred_pages,
                    SUM(CASE WHEN preferred = 0 THEN 1 ELSE 0 END) AS duplicate_pages,
                    SUM(CASE WHEN drawing_number != 'NO DRAWING NUMBER EXTRACTED' THEN 1 ELSE 0 END) AS numbers,
                    SUM(CASE WHEN title != 'DRAWING TITLE NOT FOUND' THEN 1 ELSE 0 END) AS titles,
                    SUM(CASE WHEN drawing_number = 'NO DRAWING NUMBER EXTRACTED'
                              OR title = 'DRAWING TITLE NOT FOUND' THEN 1 ELSE 0 END) AS unresolved,
                    SUM(CASE WHEN cad_path <> '' THEN 1 ELSE 0 END) AS cad_matches
                FROM master_pages
            """).fetchone()
            unmatched = self.conn.execute(
                "SELECT COUNT(*) FROM unmatched_cad"
            ).fetchone()[0]
        return {
            "pages": int(row["pages"] or 0),
            "preferred_pages": int(row["preferred_pages"] or 0),
            "duplicate_pages": int(row["duplicate_pages"] or 0),
            "numbers": int(row["numbers"] or 0),
            "titles": int(row["titles"] or 0),
            "unresolved": int(row["unresolved"] or 0),
            "cad_matches": int(row["cad_matches"] or 0),
            "unmatched_cad": int(unmatched or 0),
        }


