class PdfRenderWorker:
    """Render PDF previews off the Tk main thread.

    A single worker serialises PyMuPDF access, keeps the latest request only,
    caches the most recent open documents/images, and returns PIL images to Tk.
    """

    MAX_PREVIEW_PIXELS = 7_000_000

    def __init__(self, result_queue):
        self.result_queue = result_queue
        self.requests = queue.Queue(maxsize=1)
        self.stop_event = threading.Event()
        self.doc_cache = OrderedDict()
        self.image_cache = OrderedDict()
        self.thread = threading.Thread(target=self._run, name="P189PdfPreview", daemon=True)
        self.thread.start()

    def submit(self, request):
        # Drop queued stale requests. A render already in progress cannot be
        # interrupted safely, but its token will be ignored by the UI.
        try:
            while True:
                self.requests.get_nowait()
        except queue.Empty:
            pass
        try:
            self.requests.put_nowait(request)
        except queue.Full:
            pass

    def clear(self):
        self.submit({"command": "clear"})

    def close(self):
        self.stop_event.set()
        self.submit(None)
        try:
            self.thread.join(timeout=1.0)
        except Exception:
            pass
        self._close_documents()

    def _close_documents(self):
        for _key, value in list(self.doc_cache.items()):
            try:
                value[2].close()
            except Exception:
                pass
        self.doc_cache.clear()
        self.image_cache.clear()

    def _get_document(self, path):
        p = Path(path)
        stat = p.stat()
        resolved = str(p.resolve())
        signature = (int(stat.st_mtime_ns), int(stat.st_size))
        cached = self.doc_cache.get(resolved)
        if cached and cached[:2] == signature:
            self.doc_cache.move_to_end(resolved)
            return cached[2], signature, resolved
        if cached:
            try:
                cached[2].close()
            except Exception:
                pass
            self.doc_cache.pop(resolved, None)
        document = fitz.open(resolved)
        self.doc_cache[resolved] = (signature[0], signature[1], document)
        self.doc_cache.move_to_end(resolved)
        while len(self.doc_cache) > 2:
            _old_key, old_value = self.doc_cache.popitem(last=False)
            try:
                old_value[2].close()
            except Exception:
                pass
        return document, signature, resolved

    def _run(self):
        while not self.stop_event.is_set():
            try:
                request = self.requests.get(timeout=0.25)
            except queue.Empty:
                continue
            if request is None:
                break
            if request.get("command") == "clear":
                self._close_documents()
                continue

            # If more requests arrived before work began, keep only the newest.
            try:
                while True:
                    newer = self.requests.get_nowait()
                    if newer is None:
                        self.stop_event.set()
                        return
                    request = newer
            except queue.Empty:
                pass

            token = request.get("token")
            try:
                document, signature, resolved = self._get_document(request["path"])
                page_number = max(1, int(request.get("page_number", 1)))
                page_index = max(0, min(page_number - 1, document.page_count - 1))
                page = document.load_page(page_index)
                page_w = max(float(page.rect.width), 1.0)
                page_h = max(float(page.rect.height), 1.0)

                render_width = max(160, int(request.get("render_width", 700)))
                scale = render_width / page_w
                estimated_pixels = (page_w * scale) * (page_h * scale)
                if estimated_pixels > self.MAX_PREVIEW_PIXELS:
                    scale *= math.sqrt(self.MAX_PREVIEW_PIXELS / estimated_pixels)
                scale = max(0.04, min(4.0, scale))

                cache_key = (
                    resolved,
                    signature[0],
                    signature[1],
                    page_index,
                    round(scale, 4),
                )
                image = self.image_cache.get(cache_key)
                if image is None:
                    pix = page.get_pixmap(
                        matrix=fitz.Matrix(scale, scale),
                        alpha=False,
                        colorspace=fitz.csRGB,
                    )
                    image = Image.frombytes("RGB", (pix.width, pix.height), pix.samples)
                    self.image_cache[cache_key] = image
                    self.image_cache.move_to_end(cache_key)
                    while len(self.image_cache) > 5:
                        self.image_cache.popitem(last=False)
                else:
                    self.image_cache.move_to_end(cache_key)

                thumb_w = max(40, int(request.get("thumb_width", 190)))
                thumb_h = max(30, int(request.get("thumb_height", 106)))
                thumbnail = image.copy()
                thumbnail.thumbnail((thumb_w, thumb_h), Image.Resampling.BILINEAR)

                self.result_queue.put(("preview_ready", {
                    "token": token,
                    "path": request["path"],
                    "page_number": page_index + 1,
                    "total_pages": document.page_count,
                    "image": image,
                    "thumbnail": thumbnail,
                    "error": None,
                }))
            except Exception as exc:
                self.result_queue.put(("preview_ready", {
                    "token": token,
                    "path": request.get("path", ""),
                    "page_number": int(request.get("page_number", 1)),
                    "total_pages": 0,
                    "image": None,
                    "thumbnail": None,
                    "error": str(exc),
                }))


class DrawingMasterApp(tk.Tk):
    DESIGN_W = 1536
    DESIGN_H = 1024

    COLORS = {
        "navy_top": "#063970",
        "ribbon": "#0759a8",
        "ribbon_active": "#0a69bd",
        "header": "#064c91",
        "header2": "#0759a8",
        "select": "#1887ef",
        "panel": "#eef4f9",
        "white": "#ffffff",
        "line": "#d7e2eb",
        "line_dark": "#c4d3df",
        "text": "#17324a",
        "muted": "#60788d",
        "green": "#27a93f",
        "red": "#f22b2b",
        "yellow": "#dff300",
        "status": "#03457d",
    }

    def __init__(self):
        super().__init__()
        self.title(f"{APP_NAME} - by JK.ltd")
        # Use a normal native Windows application window.  This gives the app
        # standard taskbar / Alt-Tab presence and native minimize, maximize,
        # restore, resize and close behavior instead of emulating window chrome.
        self.overrideredirect(False)
        self.resizable(True, True)
        self.configure(bg=self.COLORS["navy_top"])

        self.db = DrawingDB(DB_FILE)
        self.msg_queue = queue.Queue()
        self.scan_thread = None
        self.shutdown_event = threading.Event()
        self.rebuild_cancel_event = threading.Event()
        self.rebuild_running = False
        self.rebuild_progress = 0.0
        self.rebuild_progress_text = ""
        self.config_data = self.load_config()

        self.total_rows = 0
        self.page_rows = []
        self.selected_id = None
        self._selected_row_cache = None
        self.current_page = 1
        self.page_size = 15
        self.sort_column = "page"
        self.sort_reverse = False

        # Lightweight PDF thumbnail preview. Rendering is off the Tk thread,
        # debounced, latest-request-only and intentionally low resolution so it
        # does not slow table selection/search/indexing.
        self.preview_worker = PdfRenderWorker(self.msg_queue)
        self.preview_token = 0
        self.preview_job = None
        self.preview_photo = None
        self.preview_payload = None

        self._drag_origin = None
        self._maximized = False
        self._normal_scale = None
        self.ui_scale_x = 1.0
        self.ui_scale_y = 1.0
        self._dynamic_images = []
        self._sprite_cache = {}

        self._skin_photo_cache = OrderedDict()
        self._font_measure_cache = {}
        self._clip_cache = OrderedDict()
        self._cached_stats = None
        self._cached_source_counts = None
        self._search_job = None
        self._destroying = False
        self._table_scroll_drag = None
        self._native_resize_job = None
        self._last_client_size = None

        if Image is None or ImageTk is None:
            messagebox.showerror(
                APP_NAME,
                "Pillow is required for the exact visual skin.\n\nInstall with:\n\npython -m pip install pillow",
            )
            self.destroy()
            return

        self.protocol("WM_DELETE_WINDOW", self._shutdown)
        self._load_skin()
        self._choose_initial_scale()
        self._build_exact_ui()
        self.refresh_table(reset_page=True)
        self.after(60, self.process_queue)
        # Native window chrome makes this a normal Windows program.
        self.bind("<Configure>", self._on_native_configure, add="+")
        self.after(80, self._set_native_app_icon)
        self.after(120, self._apply_windows_blue_titlebar)
        self.bind("<Map>", lambda _e: self.after(20, self._apply_windows_blue_titlebar), add="+")

    def _apply_windows_blue_titlebar(self):
        """Theme the native Windows caption dark blue with white controls/text."""
        if platform.system() != "Windows":
            return
        try:
            import ctypes

            self.update_idletasks()
            hwnd = ctypes.windll.user32.GetParent(self.winfo_id())
            if not hwnd:
                hwnd = self.winfo_id()

            dwm = ctypes.windll.dwmapi

            # Windows 10/11 immersive dark caption buttons. Attribute 20 is
            # current; 19 is used by some older Windows 10 builds.
            dark = ctypes.c_int(1)
            for attr in (20, 19):
                try:
                    dwm.DwmSetWindowAttribute(
                        hwnd, attr, ctypes.byref(dark), ctypes.sizeof(dark)
                    )
                except Exception:
                    pass

            def colorref(hex_color):
                value = hex_color.lstrip("#")
                r = int(value[0:2], 16)
                g = int(value[2:4], 16)
                b = int(value[4:6], 16)
                return ctypes.c_int(r | (g << 8) | (b << 16))

            # DWM attributes available on modern Windows 10/11. Fail softly
            # on older builds so the application still behaves normally.
            caption = colorref(self.COLORS["navy_top"])
            border = colorref(self.COLORS["navy_top"])
            text = colorref("#ffffff")
            for attr, value in ((35, caption), (34, border), (36, text)):
                try:
                    dwm.DwmSetWindowAttribute(
                        hwnd, attr, ctypes.byref(value), ctypes.sizeof(value)
                    )
                except Exception:
                    pass

            # Ask Windows to repaint the non-client area immediately.
            SWP_NOSIZE = 0x0001
            SWP_NOMOVE = 0x0002
            SWP_NOZORDER = 0x0004
            SWP_NOACTIVATE = 0x0010
            SWP_FRAMECHANGED = 0x0020
            ctypes.windll.user32.SetWindowPos(
                hwnd, 0, 0, 0, 0, 0,
                SWP_NOSIZE | SWP_NOMOVE | SWP_NOZORDER |
                SWP_NOACTIVATE | SWP_FRAMECHANGED,
            )
        except Exception:
            pass

    def _set_native_app_icon(self):
        """Show the P189 icon in the native Windows title bar/task panel."""
        try:
            # Keep the ICO separate from the Python source. The BAT builder adds
            # the same ICO as a PyInstaller data file as well as using --icon.
            # This lets Tk load the icon for the native window caption while the
            # EXE itself also carries the Windows Explorer/taskbar icon resource.
            icon_name = "P189_Option5_App_Icon_TRANSPARENT.ico"
            candidates = []

            if getattr(sys, "frozen", False):
                bundle_dir = Path(getattr(sys, "_MEIPASS", Path(sys.executable).parent))
                candidates.append(bundle_dir / icon_name)
                candidates.append(Path(sys.executable).resolve().parent / icon_name)
            else:
                candidates.append(Path(__file__).resolve().parent / icon_name)

            for icon_path in candidates:
                if icon_path.is_file():
                    self.iconbitmap(default=str(icon_path))
                    break
        except Exception:
            pass

    def _on_native_configure(self, event):
        """Resize the themed client area whenever Windows resizes the app."""
        if self._destroying or event.widget is not self:
            return
        w = max(1, int(event.width))
        h = max(1, int(event.height))
        if self._last_client_size == (w, h):
            return
        self._last_client_size = (w, h)
        if self._native_resize_job is not None:
            try:
                self.after_cancel(self._native_resize_job)
            except Exception:
                pass
        self._native_resize_job = self.after(45, lambda: self._resize_native_client(w, h))

    def _resize_native_client(self, width, height):
        self._native_resize_job = None
        if self._destroying or not hasattr(self, "canvas"):
            return
        try:
            width = max(800, int(width))
            height = max(560, int(height))
            self.ui_scale_x = max(0.50, width / self.DESIGN_W)
            self.ui_scale_y = max(0.50, height / self.DESIGN_H)
            self.ui_scale = min(self.ui_scale_x, self.ui_scale_y)
            self.window_w = width
            self.window_h = height
            self._font_measure_cache.clear()
            self.canvas.configure(width=width, height=height)
            self._apply_skin_image()
            self.category_combo.configure(font=self._font(8))
            self.category_combo.place(x=self.X(835), y=self.Y(18), width=self.X(230), height=self.Y(27))
            self.search_entry.configure(font=self._font(9))
            self.search_entry.place(x=self.X(1135), y=self.Y(19), width=self.X(365), height=self.Y(24))
            self.table_page_entry.configure(font=self._font(9))
            self.table_page_entry.place(x=self.X(889), y=self.Y(925), width=self.X(42), height=self.Y(28))
            self._draw_dynamic()
        except tk.TclError:
            pass

    def _load_skin(self):
        raw = base64.b64decode(SKIN_B64)
        image = Image.open(io.BytesIO(raw))
        image.load()
        self.skin_original = image if image.mode == "RGB" else image.convert("RGB")

    def _choose_initial_scale(self):
        screen_w = max(800, self.winfo_screenwidth())
        screen_h = max(600, self.winfo_screenheight())
        self._normal_scale = min(1.0, (screen_w - 24) / self.DESIGN_W, (screen_h - 48) / self.DESIGN_H)
        self.ui_scale = max(0.55, self._normal_scale)
        self.ui_scale_x = self.ui_scale
        self.ui_scale_y = self.ui_scale
        self.window_w = int(round(self.DESIGN_W * self.ui_scale_x))
        self.window_h = int(round(self.DESIGN_H * self.ui_scale_y))
        x = max(0, (screen_w - self.window_w) // 2)
        y = max(0, (screen_h - self.window_h) // 2)
        self.geometry(f"{self.window_w}x{self.window_h}+{x}+{y}")
        self.minsize(max(900, int(self.DESIGN_W * 0.58)), max(620, int(self.DESIGN_H * 0.58)))

    def X(self, value):
        return int(round(float(value) * self.ui_scale_x))

    def Y(self, value):
        return int(round(float(value) * self.ui_scale_y))

    def F(self, size):
        # Use the smaller axis for fonts so text remains readable and is not
        # distorted when the maximized window fills a widescreen monitor.
        return max(7, int(round(float(size) * min(self.ui_scale_x, self.ui_scale_y))))

    def _font(self, size=9, weight="normal"):
        return ("Segoe UI", self.F(size), weight)

    def _build_exact_ui(self):
        self.canvas = tk.Canvas(
            self,
            width=self.window_w,
            height=self.window_h,
            highlightthickness=0,
            bd=0,
            bg=self.COLORS["panel"],
        )
        self.canvas.pack(fill="both", expand=True)
        self._apply_skin_image()

        # Compact top ribbon controls. Home, Settings and Help are intentionally removed.
        self.category_var = tk.StringVar(value="ALL")
        self.category_combo = ttk.Combobox(
            self,
            textvariable=self.category_var,
            state="readonly",
            font=self._font(8),
        )
        self.category_combo.place(
            x=self.X(835), y=self.Y(18), width=self.X(230), height=self.Y(27)
        )
        self.category_combo.bind("<<ComboboxSelected>>", lambda _e: self.refresh_table(reset_page=True))

        self.search_var = tk.StringVar()
        self.search_entry = tk.Entry(
            self,
            textvariable=self.search_var,
            bd=0,
            relief="flat",
            bg="white",
            fg="#4e6377",
            insertbackground="#164a7b",
            font=self._font(9),
        )
        self.search_entry.place(
            x=self.X(1135), y=self.Y(19), width=self.X(365), height=self.Y(24)
        )
        self.search_entry.bind("<KeyRelease>", self._schedule_search)
        self._refresh_category_filter()

        self.table_page_var = tk.StringVar(value="1")
        self.table_page_entry = tk.Entry(
            self,
            textvariable=self.table_page_var,
            justify="center",
            bd=1,
            relief="solid",
            bg="white",
            fg=self.COLORS["text"],
            font=self._font(9),
        )
        self.table_page_entry.place(
            x=self.X(889), y=self.Y(925), width=self.X(42), height=self.Y(28)
        )
        self.table_page_entry.bind("<Return>", self._goto_table_page_from_entry)

        self.canvas.bind("<ButtonPress-1>", self._canvas_press)
        self.canvas.bind("<B1-Motion>", self._canvas_drag)
        self.canvas.bind("<ButtonRelease-1>", self._canvas_release)
        self.canvas.bind("<Double-Button-1>", self._canvas_double_click)
        self.canvas.bind("<MouseWheel>", self._table_mousewheel)
        self.canvas.bind("<Button-4>", self._table_mousewheel)
        self.canvas.bind("<Button-5>", self._table_mousewheel)
        self.bind("<Up>", lambda _e: self._move_selection(-1))
        self.bind("<Down>", lambda _e: self._move_selection(1))
        self.bind("<Prior>", lambda _e: self._change_table_page(-1))
        self.bind("<Next>", lambda _e: self._change_table_page(1))

        self.after(30, self._draw_dynamic)

    def _apply_skin_image(self):
        key = (int(self.window_w), int(self.window_h))
        photo = self._skin_photo_cache.get(key)
        if photo is None:
            if key == self.skin_original.size:
                resized = self.skin_original
            else:
                # BICUBIC is visually indistinguishable for this background skin
                # but much faster than LANCZOS during maximise / restore.
                resized = self.skin_original.resize(key, Image.Resampling.BICUBIC)
            photo = ImageTk.PhotoImage(resized)
            self._skin_photo_cache[key] = photo
            self._skin_photo_cache.move_to_end(key)
            while len(self._skin_photo_cache) > 3:
                self._skin_photo_cache.popitem(last=False)
        else:
            self._skin_photo_cache.move_to_end(key)

        self.skin_photo = photo
        self.canvas.delete("skin")
        self.canvas.create_image(0, 0, anchor="nw", image=self.skin_photo, tags=("skin",))
        self.canvas.tag_lower("skin")
        self._prepare_sprites()

    def _prepare_sprites(self):
        self._sprite_cache.clear()
        crops = {
            "check_green": (644, 237, 670, 264),
            "check_yellow": (644, 489, 670, 516),
            "cross_red": (644, 746, 670, 775),
            "lookup_blue": (746, 236, 775, 265),
            "lookup_white": (746, 488, 775, 516),
            "cad_thumb": (1063, 745, 1283, 857),
            "pdf_icon": (807, 865, 840, 904),
            "cad_icon": (1058, 865, 1092, 906),
        }
        for key, box in crops.items():
            crop = self.skin_original.crop(box)
            w = max(1, self.X(box[2] - box[0]))
            h = max(1, self.Y(box[3] - box[1]))
            crop = crop.resize((w, h), Image.Resampling.LANCZOS)
            self._sprite_cache[key] = ImageTk.PhotoImage(crop)

        # Rebuild the register header background from the exact skin, with its
        # original blue gradient but without any baked-in column text or rules.
        source = self.skin_original.crop((14, 184, 786, 226)).convert("RGB")
        clean = Image.new("RGB", source.size)
        pixels = source.load()
        width, height = source.size
        for yy in range(height):
            row = [pixels[xx, yy] for xx in range(width)]
            midpoint = len(row) // 2
            r = sorted(pixel[0] for pixel in row)[midpoint]
            g = sorted(pixel[1] for pixel in row)[midpoint]
            b = sorted(pixel[2] for pixel in row)[midpoint]
            clean.paste((r, g, b), (0, yy, width, yy + 1))
        clean = clean.resize((self.X(772), self.Y(42)), Image.Resampling.LANCZOS)
        self._sprite_cache["table_header_bg"] = ImageTk.PhotoImage(clean)

    def _rebuild_scaled_ui(self, scale_x, x, y, scale_y=None):
        # Normal/restored mode uses a uniform scale.  Maximized mode may use
        # separate X/Y scales so the custom borderless window truly fills the
        # Windows work area instead of merely enlarging while preserving the
        # 3:2 design aspect ratio.
        if scale_y is None:
            scale_y = scale_x
        self.ui_scale_x = max(0.50, float(scale_x))
        self.ui_scale_y = max(0.50, float(scale_y))
        self.ui_scale = min(self.ui_scale_x, self.ui_scale_y)
        self._font_measure_cache.clear()
        self.window_w = int(round(self.DESIGN_W * self.ui_scale_x))
        self.window_h = int(round(self.DESIGN_H * self.ui_scale_y))
        self.geometry(f"{self.window_w}x{self.window_h}+{int(x)}+{int(y)}")
        self.canvas.configure(width=self.window_w, height=self.window_h)
        self._apply_skin_image()
        self.category_combo.configure(font=self._font(8))
        self.category_combo.place(x=self.X(835), y=self.Y(18), width=self.X(230), height=self.Y(27))
        self.search_entry.configure(font=self._font(9))
        self.search_entry.place(x=self.X(1135), y=self.Y(19), width=self.X(365), height=self.Y(24))
        self.table_page_entry.configure(font=self._font(9))
        self.table_page_entry.place(x=self.X(889), y=self.Y(925), width=self.X(42), height=self.Y(28))
        self._draw_dynamic()

    # ------------------------------------------------------------------
    # Window chrome
    # ------------------------------------------------------------------

    def _canvas_press(self, event):
        dx = event.x / self.ui_scale_x
        dy = event.y / self.ui_scale_y

        # The drawing register has a themed vertical scrollbar.  It is drawn on
        # the canvas so it visually matches the rest of the application rather
        # than introducing a standard Windows/Tk scrollbar.
        if self._inside(dx, dy, (1113, 226, 1122, 918)):
            self._drag_origin = None
            total_pages = max(1, math.ceil(self.total_rows / self.page_size))
            if total_pages <= 1:
                self._table_scroll_drag = None
                return
            thumb_top, thumb_bottom = self._table_scroll_thumb_bounds(total_pages)
            if thumb_top <= dy <= thumb_bottom:
                self._table_scroll_drag = (dy, self.current_page)
            else:
                self._table_scroll_drag = None
                self._scrollbar_jump_to(dy)
            return

        self._table_scroll_drag = None
        # Window movement is handled by the native Windows title bar.
        self._drag_origin = None

    def _canvas_drag(self, event):
        if self._table_scroll_drag is not None:
            dy = event.y / self.ui_scale_y
            total_pages = max(1, math.ceil(self.total_rows / self.page_size))
            if total_pages > 1:
                track_top, track_bottom = 232.0, 912.0
                track_h = track_bottom - track_top
                thumb_h = max(42.0, track_h / total_pages)
                travel = max(1.0, track_h - thumb_h)
                start_y, start_page = self._table_scroll_drag
                page_delta = int(round((dy - start_y) / travel * (total_pages - 1)))
                target = max(1, min(total_pages, start_page + page_delta))
                if target != self.current_page:
                    self._goto_table_page(target)
            return

        return

    def _canvas_release(self, event):
        dx = event.x / self.ui_scale_x
        dy = event.y / self.ui_scale_y
        if self._table_scroll_drag is not None:
            self._table_scroll_drag = None
            return
        dragged = False
        if self._drag_origin:
            sx, sy, _wx, _wy = self._drag_origin
            dragged = abs(event.x_root - sx) > 4 or abs(event.y_root - sy) > 4
        self._drag_origin = None
        if not dragged:
            self._handle_click(dx, dy)

    def _table_mousewheel(self, event):
        """Scroll the drawing register while the pointer is over the left panel."""
        try:
            dx = event.x / self.ui_scale_x
            dy = event.y / self.ui_scale_y
        except Exception:
            return
        if not (14 <= dx <= 1122 and 184 <= dy <= 960):
            return

        delta = 0
        if getattr(event, "num", None) == 4:
            delta = -1
        elif getattr(event, "num", None) == 5:
            delta = 1
        else:
            wheel = int(getattr(event, "delta", 0) or 0)
            if wheel > 0:
                delta = -1
            elif wheel < 0:
                delta = 1
        if delta:
            self._change_table_page(delta)
            return "break"

    def _table_scroll_thumb_bounds(self, total_pages=None):
        total_pages = total_pages or max(1, math.ceil(self.total_rows / self.page_size))
        track_top, track_bottom = 232.0, 912.0
        track_h = track_bottom - track_top
        if total_pages <= 1:
            return track_top, track_bottom
        thumb_h = max(42.0, track_h / total_pages)
        travel = max(0.0, track_h - thumb_h)
        ratio = (self.current_page - 1) / max(1, total_pages - 1)
        thumb_top = track_top + travel * ratio
        return thumb_top, thumb_top + thumb_h

    def _scrollbar_jump_to(self, design_y):
        total_pages = max(1, math.ceil(self.total_rows / self.page_size))
        if total_pages <= 1:
            return
        track_top, track_bottom = 232.0, 912.0
        ratio = (float(design_y) - track_top) / max(1.0, track_bottom - track_top)
        ratio = max(0.0, min(1.0, ratio))
        target = 1 + int(round(ratio * (total_pages - 1)))
        self._goto_table_page(target)

    def _canvas_double_click(self, event):
        # Native title bar owns maximize/restore behavior.
        return None

    def _minimize(self):
        self.iconify()

    def _restore_override_after_map(self):
        # Retained for compatibility with older call sites; native windows need
        # no override-redirection repair.
        return

    def _ensure_windows_taskbar_entry(self):
        # A normal decorated Tk window is already an APPWINDOW and appears in
        # the Windows taskbar / Alt-Tab list without style manipulation.
        return

    def _windows_work_area(self):
        """Return the usable desktop rectangle, excluding the Windows taskbar."""
        if platform.system() == "Windows":
            try:
                import ctypes

                class RECT(ctypes.Structure):
                    _fields_ = [
                        ("left", ctypes.c_long), ("top", ctypes.c_long),
                        ("right", ctypes.c_long), ("bottom", ctypes.c_long),
                    ]

                rect = RECT()
                SPI_GETWORKAREA = 0x0030
                if ctypes.windll.user32.SystemParametersInfoW(
                    SPI_GETWORKAREA, 0, ctypes.byref(rect), 0
                ):
                    return (
                        int(rect.left), int(rect.top),
                        max(1, int(rect.right - rect.left)),
                        max(1, int(rect.bottom - rect.top)),
                    )
            except Exception:
                pass
        return (0, 0, self.winfo_screenwidth(), self.winfo_screenheight())

    def _toggle_maximize(self):
        """Use the native Windows maximize/restore state."""
        try:
            if self.state() == "zoomed":
                self.state("normal")
            else:
                self.state("zoomed")
        except tk.TclError:
            pass

    # ------------------------------------------------------------------
    # Configuration
    # ------------------------------------------------------------------

    def load_config(self):
        defaults = {
            "master_pdfs": [],
            "additional_pdfs": [],
            "additional_pdf_roots": [],
            "cad_roots": [],
        }
        for candidate in [CONFIG_FILE] + LEGACY_CONFIG_FILES:
            try:
                if candidate.exists():
                    data = json.loads(candidate.read_text(encoding="utf-8"))
                    if isinstance(data, dict):
                        defaults.update(data)
                        if candidate != CONFIG_FILE:
                            try:
                                CONFIG_FILE.write_text(json.dumps(defaults, indent=2), encoding="utf-8")
                            except Exception:
                                pass
                        break
            except Exception:
                pass
        return defaults

    def save_config(self):
        CONFIG_FILE.write_text(json.dumps(self.config_data, indent=2), encoding="utf-8")

    def _refresh_category_filter(self):
        """Refresh the indexed category selector from SQLite."""
        values = ["ALL"] + self.db.categories()
        try:
            self.category_combo["values"] = values
        except Exception:
            return
        if self.category_var.get() not in values:
            self.category_var.set("ALL")

    def _invalidate_data_caches(self):
        self._cached_stats = None
        self._cached_source_counts = None
        self._clip_cache.clear()

    def _schedule_search(self, _event=None):
        if self._search_job is not None:
            try:
                self.after_cancel(self._search_job)
            except Exception:
                pass
        self._search_job = self.after(220, self._run_scheduled_search)

    def _run_scheduled_search(self):
        self._search_job = None
        self.refresh_table(reset_page=True)

    # ------------------------------------------------------------------
    # Dynamic drawing helpers
    # ------------------------------------------------------------------

    def _clear_dynamic(self):
        self.canvas.delete("dynamic")
        self._dynamic_images = []

    def _text(self, x, y, text, size=9, fill=None, anchor="w", weight="normal", tags=("dynamic",), **kwargs):
        return self.canvas.create_text(
            self.X(x), self.Y(y), text=text, fill=fill or self.COLORS["text"],
            font=self._font(size, weight), anchor=anchor, tags=tags, **kwargs
        )

    def _rect(self, x0, y0, x1, y1, fill, outline="", width=1, tags=("dynamic",)):
        return self.canvas.create_rectangle(
            self.X(x0), self.Y(y0), self.X(x1), self.Y(y1),
            fill=fill, outline=outline, width=max(1, self.X(width)), tags=tags
        )

    def _line(self, x0, y0, x1, y1, fill, width=1, tags=("dynamic",)):
        return self.canvas.create_line(
            self.X(x0), self.Y(y0), self.X(x1), self.Y(y1),
            fill=fill, width=max(1, self.X(width)), tags=tags
        )

    def _draw_check_symbol(self, x, y, color, tags=("dynamic",)):
        """Draw a transparent-background status check mark."""
        w = max(2, self.X(2))
        self.canvas.create_line(
            self.X(x - 7), self.Y(y),
            self.X(x - 2), self.Y(y + 5),
            self.X(x + 8), self.Y(y - 6),
            fill=color, width=w, capstyle=tk.ROUND, joinstyle=tk.ROUND, tags=tags
        )

    def _draw_cross_symbol(self, x, y, color, tags=("dynamic",)):
        """Draw a transparent-background status cross."""
        w = max(2, self.X(2))
        self.canvas.create_line(
            self.X(x - 6), self.Y(y - 6), self.X(x + 6), self.Y(y + 6),
            fill=color, width=w, capstyle=tk.ROUND, tags=tags
        )
        self.canvas.create_line(
            self.X(x + 6), self.Y(y - 6), self.X(x - 6), self.Y(y + 6),
            fill=color, width=w, capstyle=tk.ROUND, tags=tags
        )

    def _draw_duplicate_symbol(self, x, y, color, tags=("dynamic",)):
        """Draw a compact transparent stacked-page symbol for duplicate PDFs."""
        w = max(1, self.X(1))
        self.canvas.create_rectangle(
            self.X(x - 7), self.Y(y - 6), self.X(x + 4), self.Y(y + 5),
            fill="", outline=color, width=w, tags=tags
        )
        self.canvas.create_rectangle(
            self.X(x - 3), self.Y(y - 3), self.X(x + 8), self.Y(y + 8),
            fill="", outline=color, width=w, tags=tags
        )

    def _draw_lookup_symbol(self, x, y, color, tags=("dynamic",)):
        """Draw a transparent-background magnifying-glass lookup symbol."""
        w = max(1, self.X(2))
        r = 6
        self.canvas.create_oval(
            self.X(x - r), self.Y(y - r), self.X(x + r), self.Y(y + r),
            fill="", outline=color, width=w, tags=tags
        )
        self.canvas.create_line(
            self.X(x + 4), self.Y(y + 4), self.X(x + 10), self.Y(y + 10),
            fill=color, width=w, capstyle=tk.ROUND, tags=tags
        )

    def _place_sprite(self, key, x, y, anchor="center", tags=("dynamic",)):
        image = self._sprite_cache.get(key)
        if image is None:
            return
        self.canvas.create_image(self.X(x), self.Y(y), image=image, anchor=anchor, tags=tags)

    def _clip_text(self, text, width_design, size=9, weight="normal"):
        """Fast table clipping with no Tcl font-measure round trips.

        Calling tkinter.font.measure repeatedly was the largest source of table
        lag.  This estimate is intentionally slightly conservative so text never
        crosses a column boundary.
        """
        text = str(text or "")
        cache_key = (text, int(width_design), int(size), str(weight), round(self.ui_scale, 3))
        cached = self._clip_cache.get(cache_key)
        if cached is not None:
            self._clip_cache.move_to_end(cache_key)
            return cached

        # Segoe UI averages roughly 0.56-0.60 em for register text.  Uppercase
        # drawing codes run wider, so use 0.60 as a safe estimate.
        average_design_width = max(3.6, float(size) * (0.61 if text.upper() == text else 0.57))
        max_chars = max(4, int(float(width_design) / average_design_width))
        if len(text) <= max_chars:
            result = text
        elif max_chars <= 3:
            result = text[:max_chars]
        else:
            result = text[: max_chars - 3].rstrip() + "..."

        self._clip_cache[cache_key] = result
        self._clip_cache.move_to_end(cache_key)
        while len(self._clip_cache) > 4096:
            self._clip_cache.popitem(last=False)
        return result

    def _wrap_cell_text(self, text, width_design, size=8, max_lines=2):
        """Fast word-aware wrapping for table cells without Tk font measurements.

        Keeps the UI responsive while allowing long drawing titles to use the
        full height of the row instead of being truncated on a single line.
        """
        text = normalize_spaces(str(text or ""))
        cache_key = ("wrap", text, int(width_design), int(size), int(max_lines), round(self.ui_scale, 3))
        cached = self._clip_cache.get(cache_key)
        if cached is not None:
            self._clip_cache.move_to_end(cache_key)
            return cached

        average_design_width = max(3.6, float(size) * (0.61 if text.upper() == text else 0.57))
        max_chars = max(6, int(float(width_design) / average_design_width))
        if len(text) <= max_chars:
            result = text
        else:
            words = text.split()
            lines = []
            current = ""
            word_index = 0
            while word_index < len(words) and len(lines) < max_lines:
                word = words[word_index]
                candidate = word if not current else current + " " + word
                if len(candidate) <= max_chars:
                    current = candidate
                    word_index += 1
                    continue
                if current:
                    lines.append(current)
                    current = ""
                    continue
                # A single token can be longer than the cell (rare, but safe).
                lines.append(word[: max(3, max_chars - 3)].rstrip() + "...")
                word_index += 1

            if current and len(lines) < max_lines:
                lines.append(current)

            remaining = word_index < len(words)
            if remaining and lines:
                last = lines[-1]
                room = max(3, max_chars - 3)
                lines[-1] = last[:room].rstrip() + "..."
            result = "\n".join(lines[:max_lines]) if lines else self._clip_text(text, width_design, size)

        self._clip_cache[cache_key] = result
        self._clip_cache.move_to_end(cache_key)
        while len(self._clip_cache) > 4096:
            self._clip_cache.popitem(last=False)
        return result

    def _wrap_panel_filename(self, text, width_design=330, size=7, max_lines=2):
        """Wrap filenames to an exact maximum number of visible lines.

        Unlike _wrap_cell_text, this accounts for the restored-window case where
        the panel becomes narrower but Tk fonts are clamped to a readable minimum
        size.  The returned string already contains all required line breaks, so
        Canvas is not allowed to wrap it again into a third line.
        """
        text = normalize_spaces(str(text or ""))
        cache_key = ("panel_filename", text, int(width_design), int(size), int(max_lines),
                     round(self.ui_scale_x, 3), round(self.ui_scale_y, 3))
        cached = self._clip_cache.get(cache_key)
        if cached is not None:
            self._clip_cache.move_to_end(cache_key)
            return cached

        # Use actual on-screen pixels because F(size) never falls below 7 px.
        available_px = max(40.0, float(width_design) * float(self.ui_scale_x))
        font_px = float(self.F(size))
        # Conservative Segoe UI estimate with a little safety margin so Canvas
        # never needs to perform an additional implicit wrap.
        avg_char_px = max(4.0, font_px * (0.64 if text.upper() == text else 0.60))
        max_chars = max(8, int((available_px - 10.0) / avg_char_px))

        words = text.split()
        if not words:
            result = ""
        else:
            lines = []
            current = ""
            i = 0
            while i < len(words) and len(lines) < max_lines:
                word = words[i]
                candidate = word if not current else current + " " + word
                if len(candidate) <= max_chars:
                    current = candidate
                    i += 1
                    continue
                if current:
                    lines.append(current)
                    current = ""
                    continue
                # Long drawing-number-like filenames often contain no spaces.
                # Split the token itself while preserving an exact two-line cap.
                take = max(5, max_chars)
                lines.append(word[:take])
                words[i] = word[take:]
                if not words[i]:
                    i += 1

            if current and len(lines) < max_lines:
                lines.append(current)

            remaining = i < len(words) or (i < len(words) and bool(words[i]))
            if remaining and lines:
                room = max(5, max_chars - 3)
                lines[-1] = lines[-1][:room].rstrip() + "..."

            result = "\n".join(lines[:max_lines])

        self._clip_cache[cache_key] = result
        self._clip_cache.move_to_end(cache_key)
        while len(self._clip_cache) > 4096:
            self._clip_cache.popitem(last=False)
        return result

    def _draw_dynamic(self):
        if not hasattr(self, "canvas"):
            return
        self._clear_dynamic()
        if self._cached_stats is None:
            self._cached_stats = self.db.stats()
        stats = self._cached_stats
        self._draw_ribbon()
        self._draw_kpis(stats)
        # Paint a clean workspace over the baked-in mockup preview before
        # drawing the live register/sidebar.  Without this, fragments of the
        # original preview image can show through the gap between the panels.
        self._draw_workspace_background()
        self._draw_table()
        self._draw_selected_panel()
        self._draw_status(stats)

    def _draw_workspace_background(self):
        """Blank the live workspace so no baked-in preview can bleed through."""
        # Cover the entire content area occupied by the two live panels,
        # including their separator gutter and footer.
        self._rect(0, 176, 1536, 968, self.COLORS["panel"], tags=("dynamic", "workspace_bg"))
        # A deliberate neutral separator keeps the two panels visually clean.
        self._rect(1110, 184, 1125, 960, self.COLORS["panel"], tags=("dynamic", "workspace_bg"))

    def _source_counts(self):
        if self._cached_source_counts is not None:
            return self._cached_source_counts
        try:
            with self.db.lock:
                row = self.db.conn.execute(
                    "SELECT "
                    "COUNT(DISTINCT CASE WHEN source_type='BOUND' THEN pdf_path END) AS bound_count, "
                    "COUNT(DISTINCT CASE WHEN source_type='UNBOUND' THEN pdf_path END) AS unbound_count, "
                    "SUM(CASE WHEN preferred=1 AND cad_path<>'' THEN 1 ELSE 0 END) AS preferred_cad "
                    "FROM master_pages"
                ).fetchone()
            result = (
                int(row["bound_count"] or 0),
                int(row["unbound_count"] or 0),
                int(row["preferred_cad"] or 0),
            )
        except Exception:
            result = (
                len(self.config_data.get("master_pdfs", [])),
                len(self.config_data.get("additional_pdfs", [])),
                0,
            )
        self._cached_source_counts = result
        return result

    def _draw_ribbon(self):
        """Use the former empty top band without disturbing the live panels."""
        self._rect(0, 0, 1536, 102, self.COLORS["ribbon"])

        # Put all working controls in the band that used to be wasted by the
        # removed custom title bar.  The KPI/register/right-panel geometry below
        # remains untouched, which keeps the stable panel alignment intact.
        buttons = [
            (18, 150, "FOLDERS / FILES"),
            (160, 302, "REBUILD INDEX"),
            (312, 438, "EXPORT CSV"),
        ]
        for x0, x1, label in buttons:
            self._rect(x0, 8, x1, 54, self.COLORS["ribbon"], "#2e79b8")
            self._text((x0+x1)/2, 31, label, 8, "white", "center", "bold")

        self._text(770, 31, "Category", 8, "white", "w", "bold")
        self._text(1080, 31, "Search", 8, "white", "w", "bold")

        # The lower part of the ribbon is now a compact project identity/status
        # strip instead of dead space.  It adds useful context without changing
        # any panel, table, scrollbar or hit-test coordinates.
        self._line(14, 67, 1522, 67, "#3a83bb", 1)
        self._text(18, 84, "P189 OPERA HOUSE  •  MASTER DRAWING REGISTER", 7, "#e9f5ff", "w", "bold")
        self._text(1510, 84, "PDF ↔ CAD INDEX", 7, "#d7ebfa", "e", "bold")

    def _draw_kpis(self, stats):
        bound, unbound, preferred_cad = self._source_counts()
        preferred = int(stats.get("preferred_pages", 0))
        values = [
            (preferred, "Master Drawings"),
            (bound, "Bound PDFs"),
            (unbound, "Unbound PDFs"),
            (int(stats.get("pages", 0)), "Pages Scanned"),
            (preferred_cad, "With CAD"),
            (max(0, preferred - preferred_cad), "Without CAD"),
        ]
        card_starts = [14, 226, 411, 596, 790, 954]
        card_ends = [226, 411, 596, 790, 954, 1122]
        for i, ((value, caption), x0, x1) in enumerate(zip(values, card_starts, card_ends)):
            self._rect(x0 + 61, 115, x1 - 3, 166, "#ffffff")
            self._text(x0 + 75, 132, f"{value:,}", 11, "#102b43", "w", "bold")
            self._text(x0 + 75, 154, caption, 8, "#304b62", "w")

    def _draw_table(self):
        """Wide register: most of the workspace is reserved for drawing results."""
        # The right panel is intentionally narrow.  This gives the searchable
        # register roughly 72% of the application width while keeping all file
        # actions available in a compact selected-drawing panel.
        x_cols = [14, 332, 720, 858, 918, 986, 1054, 1110]
        header_top = 184
        header_bottom = 226
        body_top = 226
        body_bottom = 918
        row_h = (body_bottom - body_top) / self.page_size

        self._rect(14, header_top, 1110, header_bottom, self.COLORS["header"])
        for x in x_cols:
            self._line(x, header_top, x, header_bottom, "#2b6ea9", 1)
        self._text(24, 205, "Drawing Number", 8, "white", "w", "bold")
        self._text(342, 205, "Drawing Title", 8, "white", "w", "bold")
        self._text(789, 205, "Category", 8, "white", "center", "bold")
        self._text(888, 205, "Rev.", 8, "white", "center", "bold")
        self._text(952, 205, "Page", 8, "white", "center", "bold")
        self._text(1020, 205, "Status", 8, "white", "center", "bold")
        self._text(1082, 205, "Lookup", 8, "white", "center", "bold")

        self._rect(14, body_top, 1110, body_bottom, "#ffffff")
        for x in x_cols:
            self._line(x, body_top, x, body_bottom, "#dbe5ed", 1)
        for i in range(self.page_size + 1):
            y = body_top + i * row_h
            self._line(14, y, 1110, y, "#dbe5ed", 1)

        for index, row in enumerate(self.page_rows):
            y0 = body_top + index * row_h
            y1 = y0 + row_h
            cy = (y0 + y1) / 2.0
            selected = int(row["id"]) == int(self.selected_id or -1)
            if selected:
                self._rect(14, y0 + 0.5, 1110, y1 - 0.5, self.COLORS["select"])
            fg = "white" if selected else "#20364a"

            duplicate_count = int(row["duplicate_count"] or 1) if "duplicate_count" in row.keys() else 1
            number_clip = 270 if duplicate_count > 1 else 294
            self._text(24, cy, self._clip_text(row["drawing_number"], number_clip, 8), 8, fg, "w")
            if duplicate_count > 1:
                self._draw_duplicate_symbol(313, cy, "white" if selected else "#e4a11b")
            # Keep long drawing titles strictly inside their own column at every
            # window size.  Canvas text otherwise has no horizontal boundary, so
            # a wide line can visually spill into Category/Page in restored mode.
            title_text = self._wrap_cell_text(row["title"], 350, 8, 2)
            self._text(
                342, cy, title_text, 8, fg, "w", justify="left",
                width=max(20, self.X(366)),
            )
            self._text(789, cy, self._clip_text(row["category"], 120, 7), 7, fg, "center")
            self._text(888, cy, self._clip_text(row["revision"] or "—", 48, 8), 8, fg, "center", "bold")
            self._text(952, cy, str(row["pdf_page"]), 8, fg, "center")

            linked = bool(row["cad_path"])
            if linked:
                self._draw_check_symbol(1000, cy, "#f4c542" if selected else "#20a85a")
                self._text(1014, cy, "Linked", 7, fg, "w")
            else:
                self._draw_cross_symbol(1000, cy, "white" if selected else "#d84545")
                self._text(1014, cy, "PDF Only", 7, fg, "w")

            # Transparent lookup icon: vector-only, with no baked-in background box.
            self._draw_lookup_symbol(1082, cy, "white" if selected else self.COLORS.get("blue", "#0b64b0"))

        total = self.total_rows
        start = (self.current_page - 1) * self.page_size + 1 if total else 0
        end = min(total, self.current_page * self.page_size)
        total_pages = max(1, math.ceil(total / self.page_size))

        # Wide footer with pagination grouped at the right edge of the register.
        self._rect(15, 919, 1110, 960, "#f7fafc")
        self._text(27, 940, f"Showing {start:,} to {end:,} of {total:,} drawings", 8, "#294866", "w")
        self._rect(820, 924, 850, 953, "#e9f1f7", "#b8cddd")
        self._text(835, 938, "|<", 7, "#17496f", "center", "bold")
        self._rect(854, 924, 884, 953, "#e9f1f7", "#b8cddd")
        self._text(869, 938, "<", 8, "#17496f", "center", "bold")
        self._text(938, 940, f"of {total_pages:,}", 8, "#294866", "w")
        self._rect(1012, 924, 1042, 953, "#e9f1f7", "#b8cddd")
        self._text(1027, 938, ">", 8, "#17496f", "center", "bold")
        self._rect(1046, 924, 1078, 953, "#e9f1f7", "#b8cddd")
        self._text(1062, 938, ">|", 7, "#17496f", "center", "bold")
        self.table_page_var.set(str(self.current_page))

        # Theme-matched register scrollbar.  This stays subtle until there are
        # enough results to scroll and tracks the existing database paging, so
        # it remains fast even with very large drawing registers.
        total_pages = max(1, math.ceil(self.total_rows / self.page_size))
        # Scrollbar lives OUTSIDE the register border, in the narrow gutter
        # between the left register and the selected-drawing panel.  This keeps
        # every data column at its full width and preserves the app's blue theme.
        self._rect(1113, 226, 1122, 918, "#e7eff5", "#c6d7e4")
        if total_pages > 1:
            thumb_top, thumb_bottom = self._table_scroll_thumb_bounds(total_pages)
            self._rect(1115, thumb_top, 1120, thumb_bottom, "#2f7fbd", "#1f69a3")
        else:
            self._rect(1115, 232, 1120, 912, "#cfdee9")

    def _draw_selected_panel(self):
        """Compact right panel: essential details and actions only."""
        tags = ("dynamic", "selected_panel_dynamic")
        row = self._get_selected_row()

        self._rect(1125, 184, 1523, 958, "#eef4f9", tags=tags)
        self._rect(1125, 184, 1523, 226, self.COLORS["header"], tags=tags)
        self._text(1140, 205, "Selected Drawing", 9, "white", "w", "bold", tags=tags)

        self._rect(1137, 240, 1511, 402, "#ffffff", "#c9d7e3", tags=tags)
        if not row:
            self._text(1152, 294, "Select a drawing", 11, "#17324a", "w", "bold", tags=tags)
            self._text(1152, 326, "Details and file actions will appear here.", 8, "#60788d", "w", tags=tags)
            return

        number = str(row["drawing_number"] or "")
        title = str(row["title"] or "")
        category = str(row["category"] or "")
        source = str(row["source_type"] or "")
        page = int(row["pdf_page"] or 1)
        pages = int(row["pdf_pages"] or 1)
        pdf_path = str(row["pdf_path"] or "")
        cad_path = str(row["cad_path"] or "")

        self._text(1152, 258, "DRAWING NUMBER", 6, "#60788d", "w", "bold", tags=tags)
        self._text(1152, 280, self._clip_text(number, 338, 9), 9, "#123b60", "w", "bold", tags=tags)
        self._text(1152, 308, "DRAWING TITLE", 6, "#60788d", "w", "bold", tags=tags)
        # Use the same responsive, hard-bounded wrapping concept as the register.
        # Long titles can use two lines, but can never spill outside this card.
        panel_title = self._wrap_cell_text(title, 330, 8, 2)
        self._text(
            1152, 334, panel_title, 8, "#17324a", "w", "bold", tags=tags,
            justify="left", width=max(20, self.X(338)),
        )
        self._text(1152, 382, self._clip_text(category, 200, 7), 7, "#38556c", "w", tags=tags)
        self._text(1494, 382, f"{source}  •  {page}/{pages}", 7, "#38556c", "e", tags=tags)

        # Compact PDF row.
        self._rect(1137, 418, 1511, 526, "#ffffff", "#c9d7e3", tags=tags)
        self._rect(1137, 418, 1511, 450, "#0d67ad", tags=tags)
        self._text(1152, 434, "PDF", 8, "white", "w", "bold", tags=tags)
        pdf_name = Path(pdf_path).name if pdf_path else "No PDF linked"
        # Keep long PDF filenames inside their card at every window size.
        pdf_display = self._wrap_panel_filename(pdf_name, 330, 7, 2)
        self._text(
            1152, 470, pdf_display, 7, "#17324a", "w", "bold", tags=tags,
            justify="left",
        )
        # File actions share one row: Open immediately beside its Folder partner.
        self._text(1152, 505, f"Page {page} of {pages}", 7, "#60788d", "w", tags=tags)
        self._rect(1338, 490, 1415, 518, "#0b79d0", tags=tags)
        self._text(1376.5, 504, "OPEN PDF", 6, "white", "center", "bold", tags=tags)
        self._rect(1421, 490, 1498, 518, "#e9f1f7", "#b8cddd", tags=tags)
        self._text(1459.5, 504, "FOLDER", 6, "#17496f", "center", "bold", tags=tags)

        # Compact CAD row.
        self._rect(1137, 542, 1511, 650, "#ffffff", "#c9d7e3", tags=tags)
        self._rect(1137, 542, 1511, 574, "#0d67ad", tags=tags)
        self._text(1152, 558, "AutoCAD / CAD", 8, "white", "w", "bold", tags=tags)
        cad_name = Path(cad_path).name if cad_path else "No CAD file linked"
        # Keep long AutoCAD/CAD filenames inside their card at every window size.
        cad_display = self._wrap_panel_filename(cad_name, 330, 7, 2)
        self._text(
            1152, 594, cad_display, 7, "#17324a", "w", "bold", tags=tags,
            justify="left",
        )
        self._text(1152, 629, "LINKED" if cad_path else "PDF ONLY", 7, "#2a8f35" if cad_path else "#c75450", "w", "bold", tags=tags)
        self._rect(1338, 614, 1415, 642, "#0b79d0" if cad_path else "#aab7c2", tags=tags)
        self._text(1376.5, 628, "OPEN CAD", 6, "white", "center", "bold", tags=tags)
        self._rect(1421, 614, 1498, 642, "#e9f1f7", "#b8cddd", tags=tags)
        self._text(1459.5, 628, "FOLDER", 6, "#17496f", "center", "bold", tags=tags)

        # Primary actions use the width instead of a large decorative block.
        self._rect(1137, 668, 1511, 710, "#0d67ad", "#09548d", tags=tags)
        self._text(1324, 689, "PDF ↔ CAD LOOKUP", 9, "white", "center", "bold", tags=tags)
        self._rect(1137, 720, 1320, 760, "#ffffff", "#b8cddd", tags=tags)
        self._text(1228, 740, "OPEN LOOKUP", 7, "#0d67ad", "center", "bold", tags=tags)
        self._rect(1328, 720, 1511, 760, "#ffffff", "#b8cddd", tags=tags)
        self._text(1419, 740, "COPY DRAWING NO.", 7, "#0d67ad", "center", "bold", tags=tags)

        # Useful compact summary instead of empty panel space.
        self._rect(1137, 780, 1511, 846, "#f7fafc", "#c9d7e3", tags=tags)
        self._text(1152, 800, "Quick actions", 7, "#60788d", "w", "bold", tags=tags)
        self._text(1152, 824, "Double-click a register row to open its PDF page.", 7, "#38556c", "w", tags=tags)

        # Small, passive PDF thumbnail preview.  It uses only the otherwise
        # unused lower part of the right panel and never blocks the UI thread.
        self._rect(1137, 858, 1511, 950, "#ffffff", "#c9d7e3", tags=tags)
        self._text(1152, 871, "PDF PREVIEW", 6, "#60788d", "w", "bold", tags=tags)
        if self.preview_payload and self.preview_payload.get("token") == self.preview_token:
            image = self.preview_payload.get("thumbnail")
            if image is not None:
                try:
                    self.preview_photo = ImageTk.PhotoImage(image)
                    self._dynamic_images.append(self.preview_photo)
                    self.canvas.create_image(self.X(1324), self.Y(908), image=self.preview_photo, anchor="center", tags=tags)
                except Exception:
                    self._text(1324, 908, "Preview unavailable", 7, "#60788d", "center", tags=tags)
            elif self.preview_payload.get("error"):
                self._text(1324, 908, "Preview unavailable", 7, "#60788d", "center", tags=tags)
        else:
            self._text(1324, 908, "Loading preview...", 7, "#60788d", "center", tags=tags)

    def _draw_rebuild_progress(self, percent=None, text=None, tags=None):
        """Draw the rebuild progress meter inside the existing bottom status bar."""
        if percent is None:
            percent = self.rebuild_progress
        if text is None:
            text = self.rebuild_progress_text or "Rebuilding index..."
        percent = max(0.0, min(100.0, float(percent)))
        tags = tags or ()

        # Left status segment: one concise activity line plus a themed meter.
        self._rect(37, 976, 1040, 1024, self.COLORS["status"], tags=tags)
        safe_text = self._clip_text(str(text), 720, 8)
        self._text(47, 989, safe_text, 8, "white", "w", "bold", tags=tags)
        self._text(914, 989, f"{percent:5.1f}%", 8, "white", "e", "bold", tags=tags)

        # Cancel is only visible while a rebuild is active.  It uses the same
        # blue status-bar styling and requests a cooperative worker stop.
        if self.rebuild_running:
            self._rect(930, 979, 1028, 1000, "#0b5f9f", "#72bdf0", tags=tags)
            self._text(979, 989, "Cancel Rebuild", 6, "white", "center", "bold", tags=tags)

        bar_x1, bar_y1, bar_x2, bar_y2 = 47, 1005, 1028, 1018
        self._rect(bar_x1, bar_y1, bar_x2, bar_y2, "#07355c", "#2b6f9f", tags=tags)
        fill_x = bar_x1 + (bar_x2 - bar_x1) * (percent / 100.0)
        if fill_x > bar_x1:
            self._rect(bar_x1, bar_y1, fill_x, bar_y2, "#36a9ff", tags=tags)

    def _draw_status(self, stats):
        bound, unbound, preferred_cad = self._source_counts()
        preferred = int(stats.get("preferred_pages", 0))
        without = max(0, preferred - preferred_cad)
        if self.rebuild_running:
            self._draw_rebuild_progress()
        else:
            self._rect(37, 976, 1040, 1024, self.COLORS["status"])
            self._text(
                47, 991,
                f"Ready    |    {preferred:,} drawings loaded    |    {bound:,} bound PDFs    |    "
                f"{unbound:,} unbound PDFs    |    {preferred_cad:,} with CAD    |    {without:,} without CAD",
                8, "white", "w"
            )
            self._text(
                47, 1012,
                "PDF Engine: PyMuPDF    |    Database: SQLite (WAL)",
                6, "#b9d9f2", "w", "bold"
            )
        self._rect(1040, 976, 1536, 1024, self.COLORS["status"])
        row = self._get_selected_row()
        if row:
            selected = f"Selected:  {row['drawing_number']}    |    Page {row['pdf_page']}"
        else:
            selected = "No drawing selected"
        # Keep the selected-drawing status on the first line and show the
        # internal-use restriction unobtrusively beneath it.
        self._text(1062, 991, selected, 8, "white", "w")
        self._text(
            1062, 1012,
            "Internal company use only. Not for external distribution, resale, or publication.",
            6, "#b9d9f2", "w", "bold"
        )

    # ------------------------------------------------------------------
    # Table / selection / pagination
    # ------------------------------------------------------------------

    def refresh_table(self, reset_page=False):
        if reset_page:
            self.current_page = 1
        search_text = self.search_var.get() if hasattr(self, "search_var") else ""
        selected_category = self.category_var.get() if hasattr(self, "category_var") else "ALL"
        self.total_rows = self.db.search_count(
            text=search_text,
            category=selected_category,
            unresolved_only=False,
            show_duplicates=False,
        )
        total_pages = max(1, math.ceil(self.total_rows / self.page_size))
        self.current_page = max(1, min(self.current_page, total_pages))
        offset = (self.current_page - 1) * self.page_size
        self.page_rows = list(self.db.search_page(
            text=search_text,
            category=selected_category,
            unresolved_only=False,
            show_duplicates=False,
            limit=self.page_size,
            offset=offset,
            sort_column=self.sort_column,
            sort_reverse=self.sort_reverse,
        ))

        visible_ids = {int(row["id"]) for row in self.page_rows}
        if self.selected_id not in visible_ids:
            self.selected_id = int(self.page_rows[0]["id"]) if self.page_rows else None
            self._selected_row_cache = self.page_rows[0] if self.page_rows else None
        else:
            self._selected_row_cache = next(
                (row for row in self.page_rows if int(row["id"]) == int(self.selected_id)),
                None,
            )
        self._draw_dynamic()

    def _schedule_small_preview(self, row=None):
        """Debounce a tiny preview render so rapid scrolling stays instant."""
        if self._destroying or not hasattr(self, "preview_worker"):
            return
        if self.preview_job is not None:
            try:
                self.after_cancel(self.preview_job)
            except Exception:
                pass
            self.preview_job = None
        row = row or self._get_selected_row()
        self.preview_token += 1
        token = self.preview_token
        self.preview_payload = None
        if not row or not row["pdf_path"]:
            return
        path = str(row["pdf_path"])
        page_number = int(row["pdf_page"] or 1)

        def submit():
            self.preview_job = None
            if self._destroying or token != self.preview_token:
                return
            self.preview_worker.submit({
                "token": token,
                "path": path,
                "page_number": page_number,
                "render_width": 360,
                "thumb_width": 338,
                "thumb_height": 68,
            })

        # 180 ms means keyboard/mouse-wheel browsing does not render pages that
        # the user only passes over.
        self.preview_job = self.after(180, submit)

    def _get_selected_row(self):
        if self.selected_id is None:
            return None
        if self._selected_row_cache is not None:
            try:
                if int(self._selected_row_cache["id"]) == int(self.selected_id):
                    return self._selected_row_cache
            except Exception:
                pass
        for row in self.page_rows:
            if int(row["id"]) == int(self.selected_id):
                self._selected_row_cache = row
                return row
        self._selected_row_cache = self.db.get_by_id(int(self.selected_id))
        return self._selected_row_cache

    def _select_row_at(self, design_y):
        body_top = 226
        body_bottom = 918
        if not (body_top <= design_y < body_bottom):
            return False
        row_h = (body_bottom - body_top) / self.page_size
        index = int((design_y - body_top) // row_h)
        if index < 0 or index >= len(self.page_rows):
            return False
        row = self.page_rows[index]
        row_id = int(row["id"])
        if row_id == int(self.selected_id or -1):
            return True
        self.selected_id = row_id
        self._selected_row_cache = row
        self._schedule_small_preview(row)
        self._draw_dynamic()
        return True

    def _move_selection(self, delta):
        if not self.page_rows:
            return
        ids = [int(row["id"]) for row in self.page_rows]
        try:
            index = ids.index(int(self.selected_id))
        except Exception:
            index = 0
        target = index + int(delta)
        total_pages = max(1, math.ceil(self.total_rows / self.page_size))
        if target < 0 and self.current_page > 1:
            self._goto_table_page(self.current_page - 1, select_last=True)
            return
        if target >= len(self.page_rows) and self.current_page < total_pages:
            self._goto_table_page(self.current_page + 1, select_last=False)
            return
        target = max(0, min(len(self.page_rows) - 1, target))
        row = self.page_rows[target]
        self.selected_id = int(row["id"])
        self._selected_row_cache = row
        self._schedule_small_preview(row)
        self._draw_dynamic()

    def _change_table_page(self, delta):
        self._goto_table_page(self.current_page + int(delta))

    def _goto_table_page(self, number, select_last=False):
        total_pages = max(1, math.ceil(self.total_rows / self.page_size))
        new_page = max(1, min(total_pages, int(number)))
        if new_page == self.current_page and self.page_rows:
            return
        self.current_page = new_page
        search_text = self.search_var.get() if hasattr(self, "search_var") else ""
        offset = (self.current_page - 1) * self.page_size
        selected_category = self.category_var.get() if hasattr(self, "category_var") else "ALL"
        self.page_rows = list(self.db.search_page(
            text=search_text,
            category=selected_category,
            unresolved_only=False,
            show_duplicates=False,
            limit=self.page_size,
            offset=offset,
            sort_column=self.sort_column,
            sort_reverse=self.sort_reverse,
        ))
        row = self.page_rows[-1] if (select_last and self.page_rows) else (self.page_rows[0] if self.page_rows else None)
        self.selected_id = int(row["id"]) if row else None
        self._selected_row_cache = row
        self._draw_dynamic()

    def _goto_table_page_from_entry(self, _event=None):
        try:
            self._goto_table_page(int(self.table_page_var.get()))
        except Exception:
            self.table_page_var.set(str(self.current_page))

    def _sort_by_design_x(self, x):
        columns = [
            (14, 332, "drawing_number"),
            (332, 720, "title"),
            (720, 858, "category"),
            (858, 918, "revision"),
            (918, 986, "page"),
            (986, 1054, "status"),
            (1054, 1110, "lookup"),
        ]
        column = next((name for x0, x1, name in columns if x0 <= x < x1), None)
        if not column or column == "lookup":
            return
        if self.sort_column == column:
            self.sort_reverse = not self.sort_reverse
        else:
            self.sort_column = column
            self.sort_reverse = False
        self.refresh_table(reset_page=True)

    # ------------------------------------------------------------------
    # Click routing
    # ------------------------------------------------------------------

    @staticmethod
    def _inside(x, y, box):
        x0, y0, x1, y1 = box
        return x0 <= x <= x1 and y0 <= y <= y1

    def _handle_click(self, x, y):
        # Window controls are provided by the native Windows title bar.

        if self.rebuild_running and self._inside(x, y, (930, 976, 1028, 1003)):
            self.cancel_rebuild()
            return

        # Simplified ribbon: Home, Settings and Help removed.
        if self._inside(x, y, (18, 8, 150, 54)):
            self.settings_window()
            return
        if self._inside(x, y, (160, 8, 302, 54)):
            self.full_rebuild()
            return
        if self._inside(x, y, (312, 8, 438, 54)):
            self.export_csv()
            return

        # Table header sorting.
        if 184 <= y <= 226 and 14 <= x <= 1110:
            self._sort_by_design_x(x)
            return

        # Table row / lookup.
        if 226 <= y < 918 and 14 <= x <= 1110:
            if self._select_row_at(y) and x >= 1054:
                self.lookup_selected()
            return

        # Table pagination.
        if self._inside(x, y, (820, 920, 850, 958)):
            self._goto_table_page(1)
            return
        if self._inside(x, y, (854, 920, 884, 958)):
            self._change_table_page(-1)
            return
        if self._inside(x, y, (1012, 920, 1042, 958)):
            self._change_table_page(1)
            return
        if self._inside(x, y, (1046, 920, 1078, 958)):
            self._goto_table_page(max(1, math.ceil(self.total_rows / self.page_size)))
            return

        # Fast selected-drawing panel actions (PDF preview removed).
        if self._inside(x, y, (1338, 490, 1415, 518)):
            self.open_selected_pdf()
            return
        if self._inside(x, y, (1421, 490, 1498, 518)):
            self.open_selected_folder()
            return
        if self._inside(x, y, (1338, 614, 1415, 642)):
            self.open_selected_cad()
            return
        if self._inside(x, y, (1421, 614, 1498, 642)):
            self.open_selected_cad_folder()
            return
        if self._inside(x, y, (1137, 720, 1320, 760)):
            self.lookup_selected()
            return
        if self._inside(x, y, (1328, 720, 1511, 760)):
            self.copy_number()
            return

    # ------------------------------------------------------------------
    # File actions
    # ------------------------------------------------------------------

    def selected_record(self):
        row = self._get_selected_row()
        if not row:
            messagebox.showinfo(APP_NAME, "Select a drawing first.")
        return row

    def open_selected_pdf(self):
        row = self.selected_record()
        if not row:
            return
        try:
            open_pdf_at_page(row["pdf_path"], row["pdf_page"])
        except Exception as exc:
            messagebox.showerror(APP_NAME, str(exc))

    def open_selected_folder(self):
        row = self.selected_record()
        if row:
            reveal_path(str(row["pdf_path"] or ""))

    def open_selected_cad(self):
        row = self.selected_record()
        if not row:
            return
        cad_path = str(row["cad_path"] or "")
        if not cad_path:
            messagebox.showinfo(APP_NAME, "No CAD file exists for this drawing.")
            return
        try:
            open_path(cad_path)
        except Exception as exc:
            messagebox.showerror(APP_NAME, str(exc))

    def open_selected_cad_folder(self):
        row = self.selected_record()
        if not row:
            return
        cad_path = str(row["cad_path"] or "")
        if not cad_path:
            messagebox.showinfo(APP_NAME, "No CAD file exists for this drawing.")
            return
        reveal_path(cad_path)

    def copy_number(self):
        row = self.selected_record()
        if not row:
            return
        self.clipboard_clear()
        self.clipboard_append(str(row["drawing_number"]))
        self.update_idletasks()

    def export_csv(self):
        # The export is an Excel workbook so column widths and alignment are preserved.
        rows = list(self.db.search(show_duplicates=False, limit=500000))
        if not rows:
            messagebox.showinfo(APP_NAME, "There are no drawing records to export.")
            return
        if Workbook is None or Alignment is None:
            messagebox.showerror(
                APP_NAME,
                "Excel export requires openpyxl.\n\nInstall it with:\npython -m pip install openpyxl",
            )
            return
        path = filedialog.asksaveasfilename(
            title="Export Drawing Register",
            defaultextension=".xlsx",
            filetypes=[("Excel Workbook", "*.xlsx")],
            initialfile="P189_Opera_House_Drawing_Register.xlsx",
        )
        if not path:
            return
        try:
            workbook = Workbook()
            sheet = workbook.active
            sheet.title = "Drawing Register"

            headers = [
                "Drawing Number", "Drawing Title", "Category", "Revision No", "PDF Source",
                "PDF Page", "Total Page", "CAD Path", "Status",
            ]
            sheet.append(headers)

            for row in rows:
                sheet.append([
                    row["drawing_number"], row["title"], row["category"], row["revision"], row["pdf_path"],
                    row["pdf_page"], row["pdf_pages"], row["cad_path"],
                    "Linked" if row["cad_path"] else "PDF Only",
                ])

                # Make PDF Source and CAD Path directly clickable in Excel.
                excel_row = sheet.max_row
                pdf_path = str(row["pdf_path"] or "").strip()
                cad_path = str(row["cad_path"] or "").strip()

                if pdf_path:
                    pdf_cell = sheet.cell(row=excel_row, column=5)  # PDF Source
                    pdf_cell.hyperlink = pdf_path
                    pdf_cell.style = "Hyperlink"

                if cad_path:
                    cad_cell = sheet.cell(row=excel_row, column=8)  # CAD Path
                    cad_cell.hyperlink = cad_path
                    cad_cell.style = "Hyperlink"

            # Exact user-requested Excel column widths.
            widths = {
                "A": 43,  # Drawing Number
                "B": 50,  # Drawing Title
                "C": 20,  # Category
                "D": 12,  # Revision No
                "E": 15,  # PDF Source
                "F": 12,  # PDF Page
                "G": 12,  # Total Page
                "H": 12,  # CAD Path
                "I": 10,  # Status
            }
            for column_letter, width in widths.items():
                sheet.column_dimensions[column_letter].width = width

            # Professional worksheet presentation while preserving requested widths.
            header_fill = PatternFill("solid", fgColor="064C91")
            header_font = Font(name="Calibri", size=11, bold=True, color="FFFFFF")
            body_font = Font(name="Calibri", size=10, color="17324A")
            alt_fill = PatternFill("solid", fgColor="F3F7FB")
            linked_fill = PatternFill("solid", fgColor="E2F0D9")
            pdf_only_fill = PatternFill("solid", fgColor="FFF2CC")
            light_border = Border(bottom=Side(style="thin", color="D9E2F3"))

            # Center every column title in Row 1 and use the application's blue theme.
            for cell in sheet[1]:
                cell.alignment = Alignment(horizontal="center", vertical="center")
                cell.fill = header_fill
                cell.font = header_font
            sheet.row_dimensions[1].height = 26

            # Body styling and subtle alternating rows.
            for row_idx in range(2, sheet.max_row + 1):
                sheet.row_dimensions[row_idx].height = 21
                if row_idx % 2 == 0:
                    for cell in sheet[row_idx]:
                        cell.fill = alt_fill
                for cell in sheet[row_idx]:
                    cell.font = body_font
                    cell.border = light_border
                    cell.alignment = Alignment(vertical="center")

            # Center the requested data columns.
            centered_columns = ("B", "C", "D", "F", "G", "I")
            for column_letter in centered_columns:
                for cell in sheet[column_letter][1:]:
                    cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=(column_letter == "B"))

            # Keep long paths readable without changing their requested widths.
            for column_letter in ("E", "H"):
                for cell in sheet[column_letter][1:]:
                    cell.alignment = Alignment(horizontal="left", vertical="center")

            # Make status visually distinct.
            for cell in sheet["I"][1:]:
                if str(cell.value or "").strip().lower() == "linked":
                    cell.fill = linked_fill
                else:
                    cell.fill = pdf_only_fill
                cell.font = Font(name="Calibri", size=10, bold=True, color="17324A")

            # Spreadsheet usability.
            sheet.freeze_panes = "A2"
            sheet.auto_filter.ref = sheet.dimensions
            sheet.sheet_view.showGridLines = False
            sheet.sheet_properties.pageSetUpPr.fitToPage = True
            sheet.page_setup.orientation = "landscape"
            sheet.page_setup.fitToWidth = 1
            sheet.page_setup.fitToHeight = 0
            sheet.print_title_rows = "1:1"
            sheet.print_options.horizontalCentered = True
            sheet.sheet_view.zoomScale = 90

            workbook.save(path)
            messagebox.showinfo(APP_NAME, f"Drawing register exported to:\n\n{path}")
        except Exception as exc:
            messagebox.showerror(APP_NAME, f"Export failed:\n\n{exc}")

    def show_help(self):
        messagebox.showinfo(
            APP_NAME,
            "P189 Opera House Master Drawing Look Up\n\n"
            "- Add bound/master PDFs, unbound PDFs, PDF folders and CAD folders in Folders / Files.\n"
            "- Rebuild Index scans each PDF page and then matches CAD files by drawing number.\n"
            "- Search by drawing number, title, PDF name or category.\n"
            "- Select a row to view drawing and linked-file details.\n"
            "- The Status column shows Linked or PDF Only; click Lookup for combined PDF and CAD details.\n"
        )

